window.JOURNEY_DATA = [
  { id: '1', num: 1, category: 'makkah', icon: '🕋', title: 'قبل البعثة', location: 'مكة المكرمة', date: 'قبل 570م', summary: 'جزيرة العرب قبل الإسلام: من دعوة إبراهيم إلى عام الفيل.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=1', history: 'تبدأ القصة ببيتٍ رفع قواعده إبراهيم وابنه إسماعيل عليهما السلام في وادٍ غير ذي زرع، فصارت مكة مهوى أفئدة العرب ومقصد حجّهم. ومع تطاول القرون دخلت الوثنية على دين إبراهيم، فنُصبت الأصنام حول الكعبة، وبقيت قلة من الحنفاء على التوحيد. وآلت ولاية البيت إلى قريش منذ جمعها قصي بن كلاب، فتولّت السقاية والرفادة وخدمة الحجيج، وسنّ هاشم بن عبد مناف رحلتي الشتاء إلى اليمن والصيف إلى الشام، فأمنت قريش بجوار البيت واتسعت تجارتها.\n\nوكانت الجزيرة يومئذ على أطراف إمبراطوريتين متصارعتين هما فارس والروم، بلا دولة جامعة ولا كتاب يحتكم إليه الناس، مع ما عُرف به أهلها من الوفاء والكرم والنجدة. وقبيل مولد النبي ﷺ سار أبرهة الحبشي والي اليمن بجيش يتقدمه الفيل ليهدم الكعبة ويصرف العرب إلى كنيسته «القُلَّيس» بصنعاء، فقال له عبد المطلب كلمته المشهورة: «أنا ربّ الإبل، وإنّ للبيت ربًّا سيمنعه». وأهلك الله الجيش كما قصّت سورة الفيل، فازدادت مكانة البيت وأهله في نفوس العرب، وأرّخوا بذلك العام.', details: '<p class="summary-text">بيت رفع قواعده إبراهيم، وقريش تسود مكة بالرفادة والسقاية وتتاجر شتاءً وصيفًا، في عالم مظلم بين فارس والروم، حتى عام الفيل.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  ثُمَّ إنَّ أَبْرَهَةَ بَنَى الْقُلَّيْسَ بِصَنْعَاءَ، فَبَنَى كَنِيسَةً لَمْ يُرَ مِثْلُهَا فِي زَمَانِهَا بِشَيْءِ مِنْ الْأَرْضِ، ثُمَّ كَتَبَ إلَى النَّجَاشِيِّ: إنِّي قَدْ بَنَيْتُ لَكَ أَيُّهَا الْمَلِكُ كَنِيسَةً لَمْ يُبْنَ مِثْلُهَا لِمَلِكِ كَانَ قَبْلَكَ، وَلَسْتُ بِمُنْتَهٍ حَتَّى أَصْرِفَ إلَيْهَا حَجَّ الْعَرَبِ، فَلَمَّا تَحَدَّثَتْ الْعَرَبُ بِكِتَابِ أَبْرَهَةَ ذَلِكَ إلَى النَّجَاشِيِّ، غَضِبَ رَجُلٌ مِنْ النَّسَأَةِ، أَحَدُ بَنِي فُقَيْمِ ابْن عَدِيِّ بْنِ عَامِرِ بْنِ ثَعْلَبَةَ بْنِ الْحَارِثِ بْنِ مَالِكِ بْنِ كِنَانَةَ بْنِ خُزَيْمَةَ بْنِ مُدْرِكَةَ بْنِ إلْيَاسَ مِنْ مُضَرَ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص43 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '2', num: 2, category: 'makkah', icon: '🕋', title: 'المولد النبوي', location: 'مكة المكرمة', date: '570م', summary: 'وُلد النبي ﷺ في مكة يتيم الأب، في عام الفيل.', lat: 21.4230, lng: 39.8260, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=2', history: 'وُلد محمد بن عبد الله بن عبد المطلب الهاشمي القرشي ﷺ بمكة يوم الاثنين من شهر ربيع الأول عام الفيل، وهو ما يوافق نحو سنة 570 أو 571 للميلاد على اختلاف بين المؤرخين في تحديد اليوم والسنة. وكان أبوه عبد الله قد توفي بيثرب وأمه آمنة بنت وهب حامل به على المشهور، فوُلد يتيم الأب. ولما وضعته أرسلت إلى جده عبد المطلب تبشّره، فأخذه ودخل به الكعبة يدعو الله ويشكره، وسمّاه محمدًا، وهو اسم لم يكن شائعًا عند العرب.\n\nوقد ثبت في صحيح مسلم أن النبي ﷺ سُئل عن صوم يوم الاثنين فقال: «ذاك يوم وُلدت فيه، ويوم بُعثت أو أُنزل عليّ فيه». أرضعته أيامًا ثويبة مولاة أبي لهب، ثم التُمست له المراضع في البادية على عادة أشراف مكة. ويلتقي نسبه ﷺ ببطون قريش كلها، فهو من أوسطها نسبًا وأشرفها بيتًا، وقد نشأ يتيمًا فكانت رعاية الله له سابقة لكل رعاية.', details: '<p class="summary-text">وُلد محمد بن عبد الله ﷺ بمكة عام الفيل يوم الاثنين، يتيم الأب.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: وُلِدَ رَسُولِ اللَّهِ صلى الله عليه وسلم يَوْمَ الِاثْنَيْنِ، لِاثْنَتَيْ عَشْرَةَ لَيْلَةً خَلَتْ مِنْ شَهْرِ رَبِيعٍ الْأَوَّلِ، عَامَ الْفِيلِ قَالَ ابْنُ إسْحَاقَ: حَدَّثَنِي الْمُطَّلِبُ بْنُ عَبْدِ اللَّهِ بْنِ قَيْسِ بْنِ مَخْرَمَةَ عَنْ أَبِيهِ عَنْ جَدِّهِ قَيْسِ بْنِ مَخْرَمَةَ، قَالَ: وَلَدْتُ أَنَا وَرَسُولُ اللَّهِ صلى الله عليه وسلم عَامَ الْفِيلِ، فَنَحْنُ لِدَانِ .\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص158 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '3', num: 3, category: 'makkah', icon: '🏛️', title: 'الاسترضاع وشق الصدر', location: 'بادية بني سعد', date: '570 - 574م', summary: 'أرضعته حليمة السعدية، وفيها وقعت حادثة شق الصدر.', lat: 21.1000, lng: 40.1000, image: 'https://images.unsplash.com/photo-1509316785289-025f5b846b35?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=3', history: 'كان من عادة أشراف مكة أن يسترضعوا أولادهم في البادية، لينشؤوا على صحة البدن وفصاحة اللسان. فقدمت نسوة من بني سعد بن بكر يلتمسن الرضعاء في سنة جدب، وكانت بينهن حليمة بنت أبي ذؤيب السعدية وزوجها الحارث بن عبد العزى. أعرضت المراضع عن الطفل اليتيم رجاء معروف الآباء، ثم أخذته حليمة حين لم تجد غيره، فرأت البركة في رحلها: درّ لبنها، وامتلأ ضرع ناقتها، وسبقت أتانها الركب، وأخصبت أرضها بعد جدب.\n\nبقي ﷺ في بادية بني سعد نحو أربع سنين، وفيها وقعت حادثة شق الصدر. روى مسلم عن أنس بن مالك أن جبريل أتاه وهو يلعب مع الغلمان، فأخذه فصرعه وشق عن قلبه، فاستخرج منه علقة وقال: «هذا حظ الشيطان منك»، ثم غسله في طست من ذهب بماء زمزم وأعاده إلى مكانه. وجاء الغلمان يسعون إلى مرضعته يقولون: إن محمدًا قد قُتل، فاستقبلوه وهو منتقع اللون. فخافت عليه حليمة وردّته إلى أمه في مكة.', details: '<p class="summary-text">أرضعته حليمة السعدية في بادية بني سعد، فنشأ على الفصاحة وصفاء الصحراء، وفيها شُق صدره.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَتْ: فرجعنا بِهِ، فو الله إنَّهُ بَعْدَ مَقْدِمِنَا (بِهِ) بِأَشْهُرِ مَعَ أَخِيهِ لَفِي بَهْمٍ لَنَا خَلْفَ بُيُوتِنَا، إذْ أَتَانَا أَخُوهُ يَشْتَدُّ ، فَقَالَ لِي وَلِأَبِيهِ: ذَاكَ أَخِي الْقُرَشِيُّ قَدْ أَخَذَهُ رَجُلَانِ عَلَيْهِمَا ثِيَابٌ بِيضٌ، فَأَضْجَعَاهُ، فَشَقَّا بَطْنَهُ، فَهُمَا يَسُوطَانِهِ . قَالَتْ: فَخَرَجْتُ أَنَا وَأَبوهُ نَحوه، فَوَجَدنَا قَائِمًا مُنْتَقَعَا وَجْهُهُ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص164 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '4', num: 4, category: 'hijra', icon: '🏛️', title: 'وفاة آمنة', location: 'الأبواء', date: '576م', summary: 'وفاة آمنة بالأبواء في طريق العودة من يثرب.', lat: 23.1044, lng: 39.0558, image: 'https://images.unsplash.com/photo-1509316785289-025f5b846b35?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=4', history: 'لما بلغ النبي ﷺ السادسة من عمره خرجت به أمه آمنة بنت وهب إلى يثرب، تزور به أخوال جده عبد المطلب من بني عدي بن النجار، ومعها حاضنته أم أيمن بركة الحبشية. أقامت عندهم نحو شهر، وهناك رأى ﷺ الدار التي تُوفي فيها أبوه عبد الله، وبقيت ذكريات تلك الزيارة في نفسه حتى حدّث بها أصحابه بعد الهجرة.\n\nوفي طريق العودة أدرك آمنة المرض، فتوفيت بالأبواء، وهي قرية بين مكة والمدينة، ودُفنت بها. فعاد الصبي مع أم أيمن إلى مكة وقد فقد أباه وأمه، وكان ﷺ يقول عن أم أيمن بعد ذلك إنها أمه بعد أمه. وفي صحيح مسلم أنه ﷺ زار قبر أمه بعد سنين طويلة، فبكى وأبكى من حوله. وهكذا اجتمع عليه اليتم من جهتيه وهو في السادسة، فانتقل إلى كفالة جده.', details: '<p class="summary-text">خرجت آمنة بابنها إلى أخواله في يثرب، وفي طريق العودة أدركها الموت بالأبواء.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  أَنَّ أُمَّ رَسُولِ اللَّهِ صلى الله عليه وسلم آمِنَةُ تُوُفِّيَتْ وَرَسُولُ اللَّهِ صلى الله عليه وسلم ابْنُ سِتِّ سِنِينَ بِالْأَبْوَاءِ، بَيْنَ مَكَّةَ وَالْمَدِينَةِ، كَانَتْ قَدْ قَدِمَتْ بِهِ عَلَى أَخْوَالِهِ مِنْ بَنِي عَدِيِّ بْنِ النَّجَّارِ، تُزِيرُهُ إيَّاهُمْ، فَمَاتَتْ وَهِيَ رَاجِعَةٌ بِهِ إلَى مَكَّةَ .\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص168 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '5', num: 5, category: 'makkah', icon: '🕋', title: 'كفالة الجد والعم', location: 'مكة المكرمة', date: '576 - 582م', summary: 'كفله جده عبد المطلب ثم عمه أبو طالب.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=5', history: 'بعد وفاة آمنة ضمّ عبد المطلب حفيده إليه، ورقّ له رقة لم يرقّها لأحد من ولده. كان لعبد المطلب فراش يوضع له في ظل الكعبة لا يجلس عليه أحد من بنيه إجلالًا له، فكان الصبي يأتي فيجلس عليه، فإذا أراد أعمامه أن يؤخروه قال: «دعوا ابني، فوالله إن له لشأنًا». ولم تطل هذه الكفالة، فقد توفي عبد المطلب والنبي ﷺ ابن ثماني سنين، بعد أن أوصى به ابنه أبا طالب، شقيق عبد الله والد النبي.\n\nقام أبو طالب بحق ابن أخيه خير قيام، وقدّمه على أولاده، وبقي يحوطه ويدافع عنه أكثر من أربعين سنة. وكان أبو طالب قليل المال كثير العيال، فعمل النبي ﷺ في صباه برعي الغنم. روى البخاري أنه ﷺ قال: «ما بعث الله نبيًّا إلا رعى الغنم»، فقال أصحابه: وأنت؟ قال: «نعم، كنت أرعاها على قراريط لأهل مكة». وفي الرعي تربية على الصبر والرحمة وحسن السياسة.', details: '<p class="summary-text">كفله جده عبد المطلب نحو سنتين، ثم عمه أبو طالب، وعمل في رعي الغنم لأهل مكة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  فَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم بَعْدَ عَبْدِ الْمُطَّلِبِ مَعَ عَمِّهِ أَبِي طَالِبٍ، وَكَانَ عَبْدُ الْمُطَّلِبِ- فِيمَا يَزْعُمُونَ- يُوصِي بِهِ عَمَّهُ أَبَا طَالِبٍ، وَذَلِكَ لِأَنَّ عَبْدَ اللَّهِ أَبَا رَسُولِ اللَّهِ صلى الله عليه وسلم، وَأَبَا طَالِبٍ أَخَوَانِ لِأَبٍ وَأُمٍّ، أُمُّهُمَا فَاطِمَةُ بِنْتُ عَمْرِو بْنِ عَائِذِ بْنِ عَبْدِ بْنِ عِمْرَانَ بْنِ مَخْزُومٍ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص179 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '6', num: 6, category: 'hijra', icon: '🗺️', title: 'الرحلة للشام الأولى', location: 'بُصرى الشام', date: '582م', summary: 'التقى بالراهب بحيرى الذي عرفه بصفات النبوة.', lat: 32.5180, lng: 36.4820, image: 'https://images.unsplash.com/photo-1565552643983-c44917a26ea3?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=6', history: 'لما بلغ النبي ﷺ الثانية عشرة على المشهور، خرج عمه أبو طالب في تجارة إلى الشام فصحبه معه. فلما نزل الركب بُصرى من أرض الشام، وكانت سوقًا عامرة على طريق القوافل، مرّوا بصومعة راهب يُعرف ببحيرى، كان عالمًا بكتب أهل دينه. يروي ابن إسحاق أن بحيرى رأى في الركب ما لفت نظره، فصنع لهم طعامًا على غير عادته، ثم جعل يتأمل الغلام ويسأله عن أحواله، ونظر إلى خاتم النبوة بين كتفيه.\n\nثم قال لأبي طالب: ارجع بابن أخيك إلى بلده واحذر عليه، فإنه كائن له شأن عظيم. فأسرع به أبو طالب عائدًا إلى مكة بعد أن فرغ من تجارته. وقد روى الترمذي أصل القصة أيضًا، وتكلّم أهل الحديث في بعض ألفاظ رواياتها وتفاصيلها، لكن أصلها مشهور عند أهل السير. وهي تدل على أن أهل الكتاب كانوا يترقبون نبيًّا قد أظلّ زمانه، وأن الغلام عاد إلى مكة ولم يأخذ عن الراهب علمًا.', details: '<p class="summary-text">صحب عمه أبا طالب في تجارته إلى الشام، فعرفه الراهب بحيرى بصفات النبوة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: ثُمَّ إنَّ أَبَا طَالِبٍ خَرَجَ فِي رَكْبٍ تَاجِرًا إلَى الشَّامِ، فَلَمَّا تَهَيَّأَ لِلرَّحِيلِ، وَأَجْمَعَ الْمَسِيرَ صَبَّ بِهِ رَسُولُ اللَّهِ صلى الله عليه وسلم فِيمَا يَزْعُمُونَ- فَرَقَّ لَهُ (أَبُو طَالِبٍ) وَقَالَ: وَاَللَّهِ لَأَخْرُجَنَّ بِهِ مَعِي، وَلَا يُفَارِقُنِي، وَلَا أُفَارِقُهُ أَبَدًا، أَوْ كَمَا قَالَ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص180 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '7', num: 7, category: 'makkah', icon: '🕋', title: 'حلف الفضول', location: 'مكة المكرمة', date: '590م', summary: 'شهد النبي حلفاً لنصرة المظلوم في دار ابن جدعان.', lat: 21.4240, lng: 39.8250, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=7', history: 'وقع حلف الفضول في شهر ذي القعدة بعد حرب الفجار، والنبي ﷺ في نحو العشرين من عمره. وسببه أن رجلًا من زبيد باليمن قدم مكة ببضاعة، فاشتراها منه العاص بن وائل السهمي ثم حبس عنه ثمنها. استعدى الرجل عليه أحلاف قريش فلم يعينوه لمكانة العاص، فصعد جبل أبي قبيس عند طلوع الشمس وقريش في أنديتها حول الكعبة، ونادى بأبيات يشكو فيها مظلمته.\n\nفقام الزبير بن عبد المطلب وقال: ما لهذا مترك. فاجتمعت بنو هاشم وبنو المطلب وبنو أسد بن عبد العزى وبنو زهرة وبنو تيم في دار عبد الله بن جدعان، لشرفه وسنّه، فتعاقدوا وتعاهدوا بالله ليكوننّ يدًا واحدة مع المظلوم على الظالم حتى يُؤدى إليه حقه، ثم مشوا إلى العاص فانتزعوا منه حق الرجل. وقد ذكر النبي ﷺ هذا الحلف بعد بعثته فقال: «لقد شهدت في دار عبد الله بن جدعان حلفًا ما أحب أن لي به حمر النعم، ولو أُدعى به في الإسلام لأجبت».', details: '<p class="summary-text">شهد النبي ﷺ حلفًا تعاهدت فيه بطون من قريش على نصرة المظلوم حتى يُرد إليه حقه.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ هِشَامٍ: وَأَمَّا حِلْفُ الْفُضُولِ فَحَدَّثَنِي زِيَادُ بْنُ عَبْدِ اللَّهِ الْبَكَّائِيُّ عَنْ مُحَمَّدِ بْنِ إسْحَاقَ قَالَ: تَدَاعَتْ قَبَائِلُ مِنْ قُرَيْشٍ إلَى حِلْفٍ، فَاجْتَمَعُوا لَهُ فِي دَارِ عَبْدِ اللَّهِ بْنِ جُدْعَانَ ابْن عَمْرِو بْنِ كَعْبِ بْنِ سَعْدِ بْنِ تَيْمِ بْنِ مُرَّةَ بْنِ كَعْبِ بْنِ لُؤَيٍّ، لِشَرَفِهِ وَسِنِّهِ، فَكَانَ حِلْفُهُمْ عِنْدَهُ: بَنُو هَاشِمٍ، وَبَنُو الْمُطَّلِبِ، وَأَسَدُ بْنُ عَبْدِ الْعُزَّى، وَزُهْرَةُ ابْن كِلَابٍ، وَتَيْمُ بْنُ مُرَّةَ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص133 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '8', num: 8, category: 'hijra', icon: '🏛️', title: 'تجارة خديجة', location: 'بُصرى الشام', date: '595م', summary: 'خرج في تجارة لخديجة وظهرت أمانته وبركته.', lat: 32.5180, lng: 36.4820, image: 'https://images.unsplash.com/photo-1565552643983-c44917a26ea3?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=8', history: 'كانت خديجة بنت خويلد الأسدية امرأة تاجرة ذات شرف ومال، تستأجر الرجال في مالها وتضاربهم عليه بشيء تجعله لهم. فلما بلغها عن محمد ﷺ صدق حديثه وعِظم أمانته وكرم أخلاقه، وكان قومه يلقبونه «الأمين»، بعثت إليه تعرض عليه أن يخرج في مالها إلى الشام تاجرًا، وتعطيه أفضل ما كانت تعطي غيره من التجار. فقبل ﷺ، وخرج في مالها ومعه غلامها ميسرة، وهو يومئذ في الخامسة والعشرين.\n\nبلغ الركب سوق بُصرى، فباع ﷺ سلعته واشترى ما أراد، ثم قفل راجعًا إلى مكة. فلما باعت خديجة ما جاء به ربحت ضعف ما كانت تربح أو قريبًا منه. وحدّثها ميسرة بما رأى في صحبته من صدق المعاملة ولين الجانب وطهارة السيرة. فكانت هذه الرحلة شاهدًا عمليًّا على أمانته في المال والتجارة، وبداية التعارف الذي انتهى بزواجه من خديجة.', details: '<p class="summary-text">خرج النبي ﷺ في تجارة لخديجة بنت خويلد إلى الشام، فكانت بداية التعارف بينهما.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: وَكَانَتْ خَدِيجَةُ بِنْتُ خُوَيْلِدٍ امْرَأَةً تَاجِرَةً ذَاتَ شَرَفٍ وَمَالٍ. تَسْتَأْجِرُ الرِّجَالَ فِي مَالِهَا وَتُضَارِبُهُمْ إيَّاهُ، بِشَيْءٍ تَجْعَلُهُ لَهُمْ، وَكَانَتْ قُرَيْشٌ قَوْمًا تُجَّارًا، فَلَمَّا بَلَغَهَا عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم مَا بَلَغَهَا، مِنْ صَدْقِ حَدِيثِهِ، وَعِظَمِ أَمَانَتِهِ، وَكَرَمِ أَخْلَاقِهِ، بَعَثَتْ إلَيْهِ فَعَرَضَتْ عَلَيْهِ أَنْ يَخْرُجَ فِي مَالٍ لَهَا إلَى الشَّامِ تَاجِرًا، وَتُعْطِيهِ أَفَضْلَ مَا كَانَتْ تُعْطِي غَيْرَهُ مِنْ التُّجَّارِ، مَعَ غُلَامٍ لَهَا يُقَالُ لَهُ مَيْسَرَةَ، فَقَبِلَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص187 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '9', num: 9, category: 'makkah', icon: '🕋', title: 'الزواج من خديجة', location: 'مكة المكرمة', date: '595م', summary: 'تزوج السيدة خديجة وعاش معها 25 سنة.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=9', history: 'بعد عودة النبي ﷺ من الشام رغبت خديجة في الزواج منه لما رأت من أمانته وخلقه، وكانت من أوسط نساء قريش نسبًا وأعظمهن شرفًا وأكثرهن مالًا، وكان كبار قومها حريصين على خطبتها. فعرضت عليه نفسها، ويُروى أن ذلك كان بواسطة صديقتها نفيسة بنت منية. فذكر ﷺ ذلك لأعمامه، فخرجوا معه حتى خطبوها إلى وليّها، وأصدقها عشرين بَكرة كما في سيرة ابن هشام.\n\nكان ﷺ في الخامسة والعشرين، وكانت خديجة في الأربعين على أشهر الروايات، وقيل دون ذلك. وهي أول امرأة تزوجها، ولم يتزوج عليها غيرها حتى توفيت، وعاشا معًا نحو خمس وعشرين سنة. ولدت له أولاده كلهم إلا إبراهيم: القاسم وبه كان يُكنى، وعبد الله، وزينب، ورقية، وأم كلثوم، وفاطمة. مات الذكور صغارًا، وأدركت البنات الإسلام فأسلمن وهاجرن. وبقي ﷺ يذكرها بالوفاء بعد وفاتها ويكرم صديقاتها.', details: '<p class="summary-text">تزوج النبي ﷺ خديجة بنت خويلد، أقرب نسائه إليه نسبًا، فعاش معها خمسًا وعشرين سنة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ هِشَامٍ: وَأَصْدَقَهَا رَسُولُ اللَّهِ صلى الله عليه وسلم عِشْرِينَ بَكْرَةً، وَكَانَتْ أَوَّلَ امْرَأَةٍ تَزَوَّجَهَا رَسُولُ اللَّهِ صلى الله عليه وسلم، وَلَمْ يَتَزَوَّجْ عَلَيْهَا غَيْرَهَا حَتَّى مَاتَتْ، رضي الله عنها. قَالَ ابْنُ إسْحَاقَ: فَوَلَدَتْ لِرَسُولِ اللَّهِ صلى الله عليه وسلم وَلَدَهُ كُلَّهُمْ إلَّا إبْرَاهِيمَ الْقَاسِمَ، وَبَهْ كَانَ يُكَنَّى صلى الله عليه وسلم، وَالطَّاهِرَ ، وَالطَّيِّبَ، وَزَيْنَبَ، وَرُقَيَّةَ، وَأُمَّ كُلْثُومٍ، وَفَاطِمَةَ، عليهم السلام.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص190 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '10', num: 10, category: 'makkah', icon: '🕋', title: 'بناء الكعبة', location: 'مكة المكرمة', date: '605م', summary: 'أعادت قريش بناء الكعبة واحتكموا للأمين.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=10', history: 'لما بلغ النبي ﷺ الخامسة والثلاثين أرادت قريش تجديد بناء الكعبة، وكانت قد وهن بناؤها من حريق وسيل جارف أصابها، وكانت جدرانها فوق القامة بقليل ولا سقف لها. واتفقوا ألا يُدخلوا في بنائها إلا مالًا طيبًا، ليس فيه مهر بغيّ ولا ربا ولا مظلمة لأحد. فقصرت بهم النفقة الطيبة، فأخرجوا من جهة الشمال جزءًا من البناء هو المعروف بالحِجر. وهاب الناس هدمها حتى ابتدأ به الوليد بن المغيرة.\n\nاقتسمت القبائل البناء، وشارك النبي ﷺ في حمل الحجارة. فلما بلغ البنيان موضع الحجر الأسود اختصموا: كل قبيلة تريد أن تنال شرف رفعه، واشتد النزاع أربع ليال أو خمسًا حتى تحالفوا واستعدوا للقتال. فأشار أبو أمية بن المغيرة، وكان أسنّهم، أن يحكّموا أول داخل من باب المسجد، فكان محمدًا ﷺ. فلما رأوه قالوا: «هذا الأمين، رضينا، هذا محمد». فطلب ثوبًا ووضع الحجر في وسطه، وأمر كل قبيلة أن تأخذ بناحية منه، فرفعوه جميعًا، ثم وضعه بيده الشريفة في مكانه، فحُقنت الدماء ورضي الجميع.', details: '<p class="summary-text">أعادت قريش بناء الكعبة، واحتكمت إلى الأمين ﷺ في وضع الحجر الأسود فحلّ النزاع بحكمة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  فَزَعَمَ بَعْضُ أهل الرِّوَايَة: أَن أَبَا أُمِّيَّةَ بْنَ الْمُغِيرَةِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرِ بْنِ مَخْزُوم، وَكَانَ عامئذ أَسَنَّ قُرَيْشٍ كُلِّهَا، قَالَ: يَا مَعْشَرَ قُرَيْشٍ، اجْعَلُوا بَيْنَكُمْ فِيمَا تَخْتَلِفُونَ فِيهِ أَوَّلَ مَنْ يَدْخُلُ مِنْ بَابِ هَذَا الْمَسْجِدِ يَقْضِي بَيْنَكُمْ فِيهِ، فَفَعَلُوا.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص197 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '11', num: 11, category: 'makkah', icon: '🏛️', title: 'التحنث في حراء', location: 'غار حراء', date: 'قبيل 610م', summary: 'حبّب إليه الخلاء فكان يتعبد في غار حراء.', lat: 21.4589, lng: 39.8594, image: '', url: 'station.html?event=11', history: 'لما اقترب النبي ﷺ من الأربعين ظهرت مقدمات النبوة. روى البخاري عن عائشة رضي الله عنها قالت: «أول ما بُدئ به رسول الله ﷺ من الوحي الرؤيا الصالحة في النوم، فكان لا يرى رؤيا إلا جاءت مثل فلق الصبح، ثم حُبّب إليه الخلاء، وكان يخلو بغار حراء فيتحنث فيه، وهو التعبد، الليالي ذوات العدد قبل أن ينزع إلى أهله ويتزود لذلك، ثم يرجع إلى خديجة فيتزود لمثلها».\n\nوغار حراء فجوة صغيرة في أعلى جبل النور شمال شرقي مكة، لا تتسع إلا لبضعة أشخاص، ويشرف الواقف عندها على مكة ونواحيها. كان ﷺ يقيم فيه شهر رمضان من كل سنة، يتعبد ويتفكر في ملكوت السماوات والأرض، بعيدًا عما كان عليه قومه من عبادة الأصنام التي لم يسجد لها قط. وكانت هذه الخلوة تهيئة ربانية لحمل الأمانة العظمى، حتى جاءه الحق وهو في الغار.', details: '<p class="summary-text">حُبّب إليه الخلاء، فكان يخلو بغار حراء الليالي ذوات العدد يتعبد ويتفكر.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ: فَقَالَ: عُبَيْدٌ- وَأَنَا حَاضِرٌ يُحَدِّثُ عَبْدَ اللَّهِ ابْن الزُّبَيْرِ وَمَنْ عِنْدَهُ مِنْ النَّاسِ-: كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُجَاوِرُ فِي حِرَاءٍ مِنْ كُلِّ سَنَةٍ شَهْرًا، وَكَانَ ذَلِكَ مِمَّا تَحَنَّثَ بِهِ قُرَيْشٌ فِي الْجَاهِلِيَّة. والتحنث التبرّر.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص235 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '12', num: 12, category: 'makkah', icon: '🏛️', title: 'نزول الوحي', location: 'غار حراء', date: '610م', summary: 'جاءه جبريل فقال: اقرأ، فكانت بداية الرسالة.', lat: 21.4589, lng: 39.8594, image: 'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=12', history: 'في شهر رمضان، والنبي ﷺ في الأربعين من عمره، نحو سنة 610 للميلاد، جاءه جبريل عليه السلام وهو في غار حراء. روى البخاري ومسلم عن عائشة رضي الله عنها أن الملك جاءه فقال: «اقرأ»، قال: «ما أنا بقارئ». قال ﷺ: «فأخذني فغطّني حتى بلغ مني الجهد ثم أرسلني»، وتكرر ذلك ثلاث مرات، ثم قال في الثالثة: «اقرأ باسم ربك الذي خلق، خلق الإنسان من علق، اقرأ وربك الأكرم، الذي علّم بالقلم، علّم الإنسان ما لم يعلم».\n\nفكانت هذه الآيات الخمس من صدر سورة العلق أول ما نزل من القرآن الكريم، وبها ابتدأت النبوة. وفي افتتاح الوحي بالأمر بالقراءة وذكر القلم والعلم، على نبي أمّي في أمة أمّية، إعلان لمكانة العلم في هذا الدين. وقد قال الله تعالى: «شهر رمضان الذي أُنزل فيه القرآن». ورجع النبي ﷺ بهذه الآيات إلى بيته يرجف فؤاده من هول ما رأى، لتبدأ مرحلة جديدة في تاريخ البشرية.', details: '<p class="summary-text">جاءه جبريل في غار حراء فقال: اقرأ، فكانت أول آيات القرآن وبداية الرسالة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم: فَجَاءَنِي جِبْرِيلُ، وَأَنَا نَائِمٌ، بِنَمَطٍ مِنْ دِيبَاجٍ فِيهِ كِتَابٌ ، فَقَالَ اقْرَأْ، قَالَ: قُلْتُ: مَا أَقْرَأُ ؟ قَالَ: فَغَتَّنِي بِهِ حَتَّى ظَنَنْتُ أَنَّهُ الْمَوْتُ، ثُمَّ أَرْسَلَنِي فَقَالَ: اقْرَأْ، قَالَ: قُلْتُ: مَا أَقْرَأُ؟ قَالَ: فَغَتَّنِي بِهِ حَتَّى ظَنَنْتُ أَنَّهُ الْمَوْتُ، ثُمَّ أَرْسَلَنِي، فَقَالَ: اقْرَأْ، قَالَ: قُلْتُ: مَاذَا أَقْرَأُ؟\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص236 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '13', num: 13, category: 'makkah', icon: '🕋', title: 'خديجة وورقة', location: 'مكة المكرمة', date: '610م', summary: 'ثبتته خديجة وانطلقت به إلى ورقة بن نوفل.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=13', history: 'رجع النبي ﷺ من غار حراء يرجف فؤاده، فدخل على خديجة رضي الله عنها وقال: «زمّلوني زمّلوني»، فزمّلوه حتى ذهب عنه الروع. ثم أخبرها الخبر وقال: «لقد خشيت على نفسي». فقالت كلمتها الخالدة التي رواها البخاري ومسلم: «كلا والله ما يخزيك الله أبدًا؛ إنك لتصل الرحم، وتحمل الكَلّ، وتكسب المعدوم، وتقري الضيف، وتعين على نوائب الحق». فاستدلت بمكارم أخلاقه على أن الله لا يضيّعه.\n\nثم انطلقت به إلى ابن عمها ورقة بن نوفل، وكان شيخًا كبيرًا قد عمي، تنصّر في الجاهلية وقرأ كتب أهل الكتاب. فلما سمع الخبر قال: «هذا الناموس الذي نزّل الله على موسى، يا ليتني فيها جذعًا، ليتني أكون حيًّا إذ يخرجك قومك». فقال ﷺ: «أوَمخرجيّ هم؟» قال: «نعم، لم يأتِ رجل قط بمثل ما جئت به إلا عودي، وإن يدركني يومك أنصرك نصرًا مؤزّرًا». ولم يلبث ورقة أن توفي. وكانت خديجة أول من آمن به وصدّقه من الناس.', details: '<p class="summary-text">رجع يرجف فؤاده فقال: زمّلوني، فثبّتته خديجة وانطلقت به إلى ورقة بن نوفل.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  ثُمَّ قَامَتْ فَجَمَعَتْ عَلَيْهَا ثِيَابَهَا، ثُمَّ انْطَلَقَتْ إلَى وَرَقَةَ بْنِ نَوْفَلِ بْنِ أَسَدِ بْنِ عَبْدِ الْعُزَّى بْنِ قُصَيٍّ، وَهُوَ ابْنُ عَمِّهَا، وَكَانَ وَرَقَةُ قَدْ تَنَصَّرَ وَقَرَأَ الْكُتُبَ، وَسَمِعَ مِنْ أَهْلِ التَّوْرَاةِ وَالْإِنْجِيلِ، فَأَخْبَرْتُهُ بِمَا أَخْبَرَهَا بِهِ رَسُولُ اللَّهِ صلى الله عليه وسلم، أَنَّهُ رَأَى وَسَمِعَ، فَقَالَ وَرَقَةُ بْنُ نَوْفَلٍ: قُدُّوسٌ قُدُّوسٌ ، وَاَلَّذِي نَفْسُ وَرَقَةَ بِيَدِهِ، لَئِنْ كُنْتِ صَدَّقْتِينِي يَا خَدِيجَةُ لَقَدْ جَاءَهُ النَّامُوسُ الْأَكْبَرُ الَّذِي كَانَ يَأْتِي مُوسَى، وَإِنَّهُ لَنَبِيُّ هَذِهِ الْأُمَّةِ، فَقُولِي لَهُ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص238 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '14', num: 14, category: 'makkah', icon: '🕋', title: 'قم فأنذر', location: 'مكة المكرمة', date: '610 - 613م', summary: 'نزل: يا أيها المدثر قم فأنذر، إيذاناً ببدء الدعوة.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=14', history: 'بعد اللقاء الأول في حراء فتر الوحي مدة اختلف العلماء في مقدارها، والأقرب أنها كانت أيامًا، فاشتاق النبي ﷺ إلى عودته. روى البخاري ومسلم عن جابر بن عبد الله أن النبي ﷺ قال وهو يحدّث عن فترة الوحي: «بينا أنا أمشي إذ سمعت صوتًا من السماء، فرفعت بصري فإذا الملك الذي جاءني بحراء جالس على كرسي بين السماء والأرض، فرُعبت منه، فرجعت فقلت: زمّلوني زمّلوني».\n\nفأنزل الله تعالى: «يا أيها المدثر، قم فأنذر، وربك فكبّر، وثيابك فطهّر، والرجز فاهجر». ثم حمي الوحي وتتابع. فكانت هذه الآيات تكليفًا بالرسالة والبلاغ بعد أن كان صدر سورة العلق إعلامًا بالنبوة، وفيها منهج الداعية: القيام بالإنذار، وتعظيم الله، وطهارة الظاهر والباطن، وهجر الأوثان، والصبر. ويذكر ابن هشام أن الوحي أبطأ مرة أخرى فقال المشركون: ودّعه ربه، فنزلت سورة الضحى: «ما ودّعك ربك وما قلى».', details: '<p class="summary-text">فتر الوحي مدة، ثم نزل: «يا أيها المدثر قم فأنذر» إيذانًا ببدء الدعوة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: ثُمَّ فَتَرَ الْوَحْيُ عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم فَتْرَةً مِنْ ذَلِكَ، حَتَّى شَقَّ ذَلِكَ عَلَيْهِ فَأَحْزَنَهُ، فَجَاءَهُ جِبْرِيلُ بِسُورَةِ الضُّحَى، يُقْسِمُ لَهُ رَبُّهُ، وَهُوَ الَّذِي أَكْرَمَهُ بِمَا أَكْرَمَهُ بِهِ، مَا وَدَّعَهُ وَمَا قَلَاهُ، فَقَالَ تَعَالَى: وَالضُّحى وَاللَّيْلِ إِذا سَجى.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص241 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '15', num: 15, category: 'makkah', icon: '🕋', title: 'دار الأرقم', location: 'مكة المكرمة', date: '610 - 613م', summary: 'بدأت الدعوة سراً واتخذ دار الأرقم مقراً.', lat: 21.4230, lng: 39.8270, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=15', history: 'بدأ النبي ﷺ دعوته سرًّا، يعرض الإسلام على من يثق به من أهله وأصحابه، واستمر ذلك نحو ثلاث سنين. فكان أول من آمن به زوجته خديجة، ثم ابن عمه علي بن أبي طالب وهو صبي في بيته، ومولاه زيد بن حارثة، وصديقه أبو بكر الصديق. ونشط أبو بكر في الدعوة، فأسلم على يديه عثمان بن عفان، والزبير بن العوام، وعبد الرحمن بن عوف، وسعد بن أبي وقاص، وطلحة بن عبيد الله. ثم تتابع السابقون الأولون، ومنهم أبو عبيدة بن الجراح، وأبو سلمة، والأرقم بن أبي الأرقم، وعثمان بن مظعون، وبلال، وخبّاب، وآل ياسر.\n\nوكان المسلمون يستخفون بصلاتهم في شعاب مكة. ثم اتخذ النبي ﷺ دار الأرقم بن أبي الأرقم المخزومي عند جبل الصفا مقرًّا يجتمع فيه بأصحابه، يتلو عليهم القرآن ويعلّمهم ويزكّيهم، بعيدًا عن أعين قريش. وفي هذه الدار تربّى الجيل الأول الذي حمل الدعوة، ودخل فيها الإسلام رجال كثر حتى أسلم عمر بن الخطاب، فخرج المسلمون منها إلى العلن.', details: '<p class="summary-text">بدأت الدعوة سرًّا، فآمن السابقون الأولون، واتخذ النبي ﷺ دار الأرقم مقرًّا لتعليمهم.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ: فَأَسْلَمَ بِدُعَائِهِ- فِيمَا بَلَغَنِي- عُثْمَانُ بْنُ عَفَّانَ بْنِ أَبِي الْعَاصِ بْنِ أُمَيَّةَ بْنِ عَبْدِ شَمْسِ بْنِ عَبْدِ مَنَافِ بْنِ قُصَيِّ بْنِ كِلَابِ بْنِ مُرَّةَ بْنِ كَعْبِ بْنِ لُؤَيِّ بْنِ غَالِبٍ وَالزُّبَيْرُ بْنُ الْعَوَّامِ بْنِ خُوَيْلِدِ بْنِ أَسَدِ بْنِ عَبْدِ الْعُزَّى بْنِ قُصَيِّ بْنِ كِلَابِ بْنِ مُرَّةَ ابْن كَعْبِ بْنِ لُؤَيٍّ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص250 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '16', num: 16, category: 'makkah', icon: '🕋', title: 'إسلام حمزة', location: 'مكة المكرمة', date: 'مبكر', summary: 'أسلم حمزة بن عبد المطلب فكان عزاً للمسلمين.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=16', history: 'كان حمزة بن عبد المطلب عم النبي ﷺ وأخاه من الرضاعة، وكان من أعزّ فتيان قريش وأشدهم شكيمة، صاحب قنص يخرج للصيد. وفي يوم من الأيام مرّ أبو جهل بالنبي ﷺ عند الصفا فآذاه وشتمه ونال منه، والنبي ﷺ ساكت لا يكلمه، وكانت مولاة لعبد الله بن جدعان تسمع ذلك من مسكنها.\n\nفلما أقبل حمزة متوشحًا قوسه راجعًا من قنصه أخبرته المولاة بما لقي ابن أخيه. فاحتمله الغضب، ودخل المسجد حتى قام على رأس أبي جهل وهو جالس في القوم، فضربه بالقوس فشجّه شجة منكرة، وقال: «أتشتمه وأنا على دينه أقول ما يقول؟ فرُدّ ذلك عليّ إن استطعت». فقام رجال من بني مخزوم لينصروا أبا جهل، فقال: دعوا أبا عمارة، فإني والله قد سببت ابن أخيه سبًّا قبيحًا. ثم شرح الله صدر حمزة للإسلام فثبت عليه، فعرفت قريش أن رسول الله ﷺ قد عزّ وامتنع، فكفّوا عن بعض ما كانوا ينالون منه. ولُقّب حمزة بأسد الله، واستُشهد يوم أحد.', details: '<p class="summary-text">أسلم حمزة، أعزّ فتى في قريش، غضبًا لابن أخيه، فكان إسلامه عزًّا للمسلمين.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: حَدَّثَنِي رَجُلٌ مِنْ أَسْلَمَ، كَانَ وَاعِيَةً: أَنَّ أَبَا جَهْلٍ مَرَّ بِرَسُولِ اللَّهِ صلى الله عليه وسلم عِنْدَ الصَّفَا، فَآذَاهُ وَشَتَمَهُ، وَنَالَ مِنْهُ بَعْضَ مَا يَكْرَهُ مِنْ الْعَيْبِ لِدِينِهِ، وَالتَّضْعِيفِ لِأَمْرِهِ، فَلَمْ يُكَلِّمْهُ رَسُولُ اللَّهِ صلى الله عليه وسلم، وَمَوْلَاةٌ لِعَبْدِ اللَّهِ بْنِ جُدْعَانَ بْنِ عَمْرِو بْنِ كَعْبِ بْنِ سَعْدِ بْنِ تَيْمِ بْنِ مُرَّةَ فِي مَسْكَنٍ لَهَا تَسْمَعُ ذَلِكَ، ثُمَّ انْصَرَفَ عَنْهُ فَعَمَدَ إلَى نَادٍ مِنْ قُرَيْشٍ عِنْدَ الْكَعْبَةِ، فَجَلَسَ مَعَهُمْ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص291 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '17', num: 17, category: 'makkah', icon: '🏛️', title: 'الجهر بالدعوة', location: 'جبل الصفا', date: '613م', summary: 'صعد الصفا ونادى بطون قريش وأعلن الدعوة.', lat: 21.4235, lng: 39.8265, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=17', history: 'بعد نحو ثلاث سنين من الدعوة السرية نزل قوله تعالى: «وأنذر عشيرتك الأقربين»، وقوله: «فاصدع بما تؤمر وأعرض عن المشركين». روى البخاري ومسلم عن ابن عباس رضي الله عنهما أن النبي ﷺ صعد على الصفا فجعل ينادي: «يا بني فهر، يا بني عدي»، لبطون قريش، حتى اجتمعوا، وجعل الرجل إذا لم يستطع أن يخرج أرسل رسولًا لينظر ما الخبر.\n\nفقال ﷺ: «أرأيتكم لو أخبرتكم أن خيلًا بالوادي تريد أن تغير عليكم، أكنتم مصدّقيّ؟» قالوا: نعم، ما جرّبنا عليك إلا صدقًا. قال: «فإني نذير لكم بين يدي عذاب شديد». فقال عمه أبو لهب: تبًّا لك سائر اليوم، ألهذا جمعتنا؟ فنزلت سورة المسد: «تبّت يدا أبي لهب وتب». وبهذا الموقف خرجت الدعوة من السر إلى العلن، وأقامت الحجة على قريش بشهادتهم هم بصدقه، وبدأت مرحلة المواجهة التي امتدت نحو عشر سنين في مكة.', details: '<p class="summary-text">نزل «وأنذر عشيرتك الأقربين»، فصعد النبي ﷺ الصفا ونادى بطون قريش وأعلن الدعوة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: ثُمَّ دَخَلَ النَّاسُ فِي الْإِسْلَامِ أَرْسَالًا مِنْ الرِّجَالِ وَالنِّسَاءِ، حَتَّى فَشَا ذِكْرُ الْإِسْلَامِ بِمَكَّةَ، وَتُحَدِّثَ بِهِ. ثُمَّ إنَّ اللَّهَ عز وجل أَمَرَ رَسُولَهُ صلى الله عليه وسلم أَنْ يَصْدَعَ بِمَا جَاءَهُ مِنْهُ، وَأَنْ يُبَادِيَ النَّاسَ بِأَمْرِهِ، وَأَنْ يَدْعُوَ إلَيْهِ، وَكَانَ بَيْنَ مَا أَخْفَى رَسُولُ اللَّهِ صلى الله عليه وسلم أَمْرَهُ وَاسْتَتَرَ بِهِ إلَى أَنْ أَمَرَهُ اللَّهُ تَعَالَى بِإِظْهَارِ دِينِهِ ثَلَاثَ سِنِينَ- فِيمَا بَلَغَنِي- مِنْ مَبْعَثِهِ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص262 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '18', num: 18, category: 'makkah', icon: '🕋', title: 'مساومة قريش', location: 'مكة المكرمة', date: '613 - 616م', summary: 'ضغطت قريش وعرضت المال فثبت النبي على دعوته.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=18', history: 'لما رأت قريش أن الدعوة تنتشر سلكت طريق الضغط والمساومة. مشى أشرافها إلى أبي طالب مرة بعد مرة يطلبون منه أن يكفّ ابن أخيه عن عيب آلهتهم وتسفيه أحلامهم، أو يخلّي بينهم وبينه. فلما كلّمه أبو طالب في ذلك، يروي ابن إسحاق أن النبي ﷺ قال: «يا عم، والله لو وضعوا الشمس في يميني والقمر في يساري على أن أترك هذا الأمر حتى يظهره الله أو أهلك فيه ما تركته». فقال أبو طالب: اذهب يا ابن أخي فقل ما أحببت، فوالله لا أسلمك لشيء أبدًا.\n\nثم جرّبوا الإغراء، فأرسلوا عتبة بن ربيعة يعرض عليه المال حتى يكون أكثرهم مالًا، والسيادة والملك، والطب إن كان ما به مرضًا. فلما فرغ تلا عليه النبي ﷺ من أول سورة فصّلت، فرجع عتبة إلى قومه بغير الوجه الذي ذهب به، وأشار عليهم أن يخلّوا بينه وبين ما هو فيه. وعرضوا أن يعبد آلهتهم سنة ويعبدوا إلهه سنة، فنزلت سورة الكافرون تقطع كل مساومة على العقيدة: «لكم دينكم ولي دين».', details: '<p class="summary-text">ضغطت قريش على أبي طالب ليكفّ ابن أخيه، ثم عرضت المال والملك، فثبت النبي ﷺ على دعوته.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  فَقَالُوا: يَا أَبَا طَالِبٍ، إنَّ ابْنَ أَخِيكَ قَدْ سَبَّ آلِهَتَنَا، وَعَابَ دِينَنَا، وَسَفَّهُ أَحْلَامَنَا، وَضَلَّلَ آبَاءَنَا، فَإِمَّا أَنْ تَكُفَّهُ عَنَّا، وَإِمَّا أَنَّ تُخِلِّي بَيْنَنَا وَبَيْنَهُ، فَإِنَّكَ عَلَى مِثْلِ مَا نَحْنُ عَلَيْهِ مِنْ خِلَافِهِ، فَنَكْفِيكَهُ فَقَالَ لَهُمْ أَبُو طَالِبٍ قَوْلًا رَفِيقًا، وَرَدَّهُمْ رَدًّا جَمِيلًا، فَانْصَرَفُوا عَنْهُ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص265 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '19', num: 19, category: 'makkah', icon: '🕋', title: 'الاضطهاد', location: 'مكة المكرمة', date: '613 - 619م', summary: 'تعذيب المستضعفين كبلال وآل ياسر.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=19', history: 'لما عجزت قريش عن صرف النبي ﷺ بالمساومة، وثبت كل قبيلة على من أسلم من أبنائها، اشتد الأذى على المستضعفين الذين لا عشيرة لهم تمنعهم. كان أمية بن خلف يُخرج بلال بن رباح إذا حميت الظهيرة، فيطرحه على ظهره في بطحاء مكة ويضع الصخرة العظيمة على صدره، فلا يزيد بلال على قوله: «أحدٌ أحد»، حتى اشتراه أبو بكر الصديق فأعتقه، وأعتق معه عددًا من المعذَّبين. وعُذّب آل ياسر، فكان النبي ﷺ يمر بهم ويقول: «صبرًا آل ياسر، فإن موعدكم الجنة». وقتل أبو جهل سمية أم عمار فكانت أول شهيدة في الإسلام، ومات ياسر تحت العذاب، وعُذّب خبّاب بن الأرتّ بالنار.\n\nولم يسلم النبي ﷺ نفسه من الأذى مع حماية عمه، فاتُّهم بالسحر والجنون والكهانة. وروى البخاري أن عقبة بن أبي معيط ألقى سلا جزور على ظهره وهو ساجد عند الكعبة، حتى جاءت فاطمة ابنته فأزالته عنه. وخنقه عقبة مرة بثوبه خنقًا شديدًا، فدفعه أبو بكر وهو يقول: «أتقتلون رجلًا أن يقول ربي الله؟».', details: '<p class="summary-text">صبّت قريش أذاها على المستضعفين كبلال وآل ياسر، ونال النبي ﷺ نصيبه من السخرية والأذى.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  وَكَانَ بَلَالٌ، مَوْلَى أَبِي بَكْرٍ رضي الله عنهما، لِبَعْضِ بَنِي جُمَحٍ، مُوَلَّدًا مِنْ مُوَلَّدِيهِمْ، وَهُوَ بَلَالُ بْنُ رَبَاحٍ، وَكَانَ اسْمُ أُمِّهِ حَمَامَةَ، وَكَانَ صَادِقَ الْإِسْلَامِ طَاهِرَ الْقَلْبِ، وَكَانَ أُمَيَّةُ بْنُ خَلَفِ بْنِ وَهْبِ بْنِ حُذَافَةَ بْنِ جُمَحٍ يُخْرِجُهُ إذَا حَمِيَتْ الظَّهِيرَةُ، فَيَطْرَحَهُ عَلَى ظَهْرِهِ فِي بَطْحَاءِ مَكَّةَ، ثُمَّ يَأْمُرُ بالصّخرة الْعَظِيمَة فتتوضع عَلَى صَدْرِهِ، ثُمَّ يَقُولُ لَهُ: (لَا وَاَللَّهِ) لَا تَزَالُ هَكَذَا حَتَّى تَمُوتَ، أَوْ تَكْفُرَ بِمُحَمَّدِ، وَتَعْبُدَ اللَّاتَ وَالْعُزَّى، فَيَقُولُ وَهُوَ فِي ذَلِكَ الْبَلَاءِ: أَحَدٌ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص317 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '20', num: 20, category: 'hijra', icon: '🗺️', title: 'الهجرة للحبشة', location: 'أكسوم - الحبشة', date: '615م', summary: 'أول هجرة فراراً بالدين إلى ملك لا يُظلم عنده أحد.', lat: 14.1310, lng: 38.7180, image: 'https://images.unsplash.com/photo-1509316785289-025f5b846b35?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=20', history: 'لما رأى النبي ﷺ ما يصيب أصحابه من البلاء وهو لا يقدر أن يمنعهم، قال لهم كما يروي ابن إسحاق: «لو خرجتم إلى أرض الحبشة، فإن بها ملكًا لا يُظلم عنده أحد، وهي أرض صدق، حتى يجعل الله لكم فرجًا مما أنتم فيه». فخرج الفوج الأول في شهر رجب من السنة الخامسة للبعثة، نحو سنة 615م، وكانوا بضعة عشر رجلًا ومعهم أربع نسوة، فيهم عثمان بن عفان وزوجته رقية بنت رسول الله ﷺ. تسللوا إلى ميناء الشعيبة على البحر الأحمر، فركبوا سفينتين للتجار حملتاهم إلى الحبشة.\n\nكانت هذه أول هجرة في الإسلام. ثم بلغ المهاجرين خبر غير صحيح أن أهل مكة أسلموا، فرجع بعضهم ليجدوا الأذى أشد مما كان. فكانت الهجرة الثانية أوسع، خرج فيها ثلاثة وثمانون رجلًا وبضع عشرة امرأة بقيادة جعفر بن أبي طالب. وأقاموا في جوار النجاشي أصحمة ملك الحبشة، وعاصمته أكسوم، آمنين على دينهم يعبدون الله لا يؤذَون. وبقي بعضهم هناك حتى قدموا على النبي ﷺ يوم خيبر في السنة السابعة للهجرة.', details: '<p class="summary-text">أذن النبي ﷺ لأصحابه بالهجرة إلى الحبشة، فكانت أول هجرة في الإسلام فرارًا بالدين.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ : فَلَمَّا رَأَى رَسُولُ اللَّهِ صلى الله عليه وسلم مَا يُصِيبُ أَصْحَابَهُ مِنْ الْبَلَاءِ، وَمَا هُوَ فِيهِ مِنْ الْعَافِيَةِ، بِمَكَانِهِ مِنْ اللَّهِ وَمِنْ عَمِّهِ أَبِي طَالِبٍ، وَأَنَّهُ لَا يَقْدِرُ عَلَى أَنْ يَمْنَعَهُمْ مِمَّا هُمْ فِيهِ مِنْ الْبَلَاءِ، قَالَ لَهُمْ: لَوْ خَرَجْتُمْ إلَى أَرْضِ الْحَبَشَةِ فَإِنَّ بِهَا مَلِكًا لَا يُظْلَمُ عِنْدَهُ أَحَدٌ، وَهِيَ أَرْضُ صِدْقٍ، حَتَّى يَجْعَلَ اللَّهُ لَكُمْ فَرَجًا مِمَّا أَنْتُمْ فِيهِ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص321 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '21', num: 21, category: 'hijra', icon: '🏛️', title: 'جعفر والنجاشي', location: 'أكسوم', date: '615 - 616م', summary: 'أفشل جعفر سفارة قريش بكلمته عن الإسلام.', lat: 14.1310, lng: 38.7180, image: 'https://images.unsplash.com/photo-1509316785289-025f5b846b35?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=21', history: 'لما رأت قريش أن المهاجرين أمنوا في الحبشة أرسلت عمرو بن العاص وعبد الله بن أبي ربيعة بهدايا من الجلود إلى النجاشي وبطارقته، يطلبان تسليمهم. وتروي أم سلمة رضي الله عنها القصة، وكانت من المهاجرين: أن النجاشي أبى أن يسلّمهم حتى يسمع منهم، فدعاهم وسألهم عن دينهم. فتكلم جعفر بن أبي طالب فقال: «أيها الملك، كنا قومًا أهل جاهلية، نعبد الأصنام، ونأكل الميتة، ونأتي الفواحش، ونقطع الأرحام، ونسيء الجوار، ويأكل القوي منا الضعيف، حتى بعث الله إلينا رسولًا منا نعرف نسبه وصدقه وأمانته وعفافه»، ثم ذكر ما دعاهم إليه من التوحيد وصدق الحديث وأداء الأمانة وصلة الرحم.\n\nثم قرأ عليه صدرًا من سورة مريم، فبكى النجاشي حتى اخضلّت لحيته وقال: «إن هذا والذي جاء به عيسى ليخرج من مشكاة واحدة». وحاول عمرو أن يوقع بينهم بسؤالهم عن عيسى عليه السلام، فقال جعفر: هو عبد الله ورسوله وروحه وكلمته ألقاها إلى مريم العذراء البتول. فأقرّ النجاشي قوله، وردّ على الرسولين هداياهما، وأقام المسلمون عنده بخير دار. ولما مات النجاشي صلّى عليه النبي ﷺ صلاة الغائب كما في الصحيحين.', details: '<p class="summary-text">أرسلت قريش عمرو بن العاص لاسترداد المهاجرين، فأفشل جعفر سفارتهم بكلمته عن الإسلام.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَتْ: ثُمَّ أَرْسَلَ إلَى أَصْحَابِ رَسُولِ اللَّهِ صلى الله عليه وسلم فَدَعَاهُمْ، فَلَمَّا جَاءَهُمْ رَسُولُهُ اجْتَمَعُوا، ثُمَّ قَالَ بَعْضُهُمْ لِبَعْضِ: مَا تَقُولُونَ لِلرَّجُلِ إذَا جِئْتُمُوهُ؟ قَالُوا: نَقُولُ: وَاَللَّهِ مَا عَلِمْنَا، وَمَا أَمَرَنَا بِهِ نَبِيُّنَا صلى الله عليه وسلم كَائِنًا فِي ذَلِكَ مَا هُوَ كَائِنٌ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص335 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '22', num: 22, category: 'makkah', icon: '🕋', title: 'إسلام عمر', location: 'مكة المكرمة', date: '616م', summary: 'أسلم عمر بن الخطاب فكان إسلامه عِزاً.', lat: 21.4230, lng: 39.8270, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=22', history: 'كان عمر بن الخطاب العدوي من أشد قريش على المسلمين، ذا قوة وهيبة. ويُروى أن النبي ﷺ دعا فقال: «اللهم أعزّ الإسلام بأحب هذين الرجلين إليك: بأبي جهل أو بعمر بن الخطاب» (رواه الترمذي). وقد أسلم عمر في السنة السادسة للبعثة بعد إسلام حمزة بأيام قليلة.\n\nوأشهر ما يُروى في إسلامه ما ذكره ابن إسحاق: أنه خرج متوشحًا سيفه يريد رسول الله ﷺ، فلقيه نُعيم بن عبد الله فأخبره أن أخته فاطمة وزوجها سعيد بن زيد قد أسلما. فذهب إليهما وعندهما خبّاب بن الأرتّ يقرئهما سورة طه، فضرب أخته فأدماها، ثم ندم لما رأى الدم وطلب الصحيفة. فلما قرأ صدر السورة قال: ما أحسن هذا الكلام وأكرمه. ثم مضى إلى الدار التي عند الصفا، فأذن له النبي ﷺ، فشهد شهادة الحق، فكبّر المسلمون تكبيرة سمعها أهل المسجد. وكان إسلامه فتحًا للمسلمين؛ روى البخاري عن عبد الله بن مسعود قال: «ما زلنا أعزّة منذ أسلم عمر».', details: '<p class="summary-text">خرج عمر يريد النبي ﷺ متوشحًا سيفه، فدخل الإيمان قلبه عند أخته، وأسلم في دار عند الصفا.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: وَلَمَّا قَدِمَ عَمْرُو بْنُ الْعَاصِ وَعَبْدُ اللَّهِ بْنُ أَبِي رَبِيعَةَ عَلَى قُرَيْشٍ، وَلَمْ يُدْرِكُوا مَا طَلَبُوا مِنْ أَصْحَابِ رَسُولِ اللَّهِ صلى الله عليه وسلم، وَرَدَّهُمَا النَّجَاشِيُّ بِمَا يَكْرَهُونَ، وَأَسْلَمَ عُمَرُ بْنُ الْخَطَّابِ، وَكَانَ رَجُلًا ذَا شَكِيمَةٍ لَا يُرَامُ مَا وَرَاءَ ظَهْرِهِ، امْتَنَعَ بِهِ أَصْحَابُ رَسُولِ اللَّهِ صلى الله عليه وسلم وَبِحَمْزَةِ حَتَّى عَازُوا قُرَيْشًا ، وَكَانَ عَبْدُ اللَّهِ بْنُ مَسْعُودٍ يَقُولُ: مَا كُنَّا نَقْدِرُ عَلَى أَنْ نُصَلِّيَ عِنْدَ الْكَعْبَةِ، حَتَّى أَسْلَمَ عُمَرُ (بْنُ الْخَطَّابِ) ، فَلَمَّا أَسْلَمَ قَاتَلَ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص342 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '23', num: 23, category: 'makkah', icon: '🕋', title: 'أسئلة اليهود', location: 'مكة المكرمة', date: 'العهد المكي', summary: 'أسئلة امتحان من أحبار يهود ونزول سورة الكهف.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=23', history: 'أرادت قريش أن تمتحن صدق النبي ﷺ بعلم أهل الكتاب، فبعثت النضر بن الحارث وعقبة بن أبي معيط إلى أحبار اليهود بيثرب يسألانهم عنه. يروي ابن إسحاق أن الأحبار قالوا: سلوه عن ثلاث، فإن أخبركم بهن فهو نبي مرسل: سلوه عن فتية ذهبوا في الدهر الأول ما كان من أمرهم، وعن رجل طوّاف بلغ مشارق الأرض ومغاربها، وعن الروح ما هي.\n\nفسألوه، فقال ﷺ: «أخبركم غدًا» ولم يستثنِ بمشيئة الله. فأبطأ عنه الوحي ليالي حتى أرجف أهل مكة وشقّ ذلك عليه. ثم نزل جبريل بسورة الكهف، وفيها خبر أصحاب الكهف، وخبر ذي القرنين، وفيها التعليم الرباني: «ولا تقولنّ لشيء إني فاعل ذلك غدًا، إلا أن يشاء الله». ونزل في الروح قوله تعالى: «ويسألونك عن الروح قل الروح من أمر ربي وما أوتيتم من العلم إلا قليلًا». فقامت الحجة على قريش بما طلبوه هم، ومع ذلك لم يؤمن أكثرهم.', details: '<p class="summary-text">أرسلت قريش إلى أحبار يهود يثرب، فأوصوهم بثلاثة أسئلة امتحانًا للنبي ﷺ، فنزل الجواب قرآنًا.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  فَلَمَّا قَالَ لَهُمْ ذَلِكَ النَّضْرُ بْنُ الْحَارِثِ بَعَثُوهُ، وَبَعَثُوا مَعَهُ عُقْبَةَ بْنَ أَبِي مُعَيْطٍ إلَى أَحْبَارِ يَهُودَ بِالْمَدِينَةِ، وَقَالُوا لَهُمَا: سَلَاهُمْ عَنْ مُحَمَّدٍ، وَصِفَا لَهُمْ صِفَتَهُ، وَأَخْبِرَاهُمْ بِقَوْلِهِ، فَإِنَّهُمْ أَهْلُ الْكِتَابِ الْأُوَلِ، وَعِنْدَهُمْ عِلْمٌ لَيْسَ عِنْدَنَا مِنْ عِلْمِ الْأَنْبِيَاءِ، فَخَرَجَا حَتَّى قَدِمَا الْمَدِينَةَ، فَسَأَلَا أَحْبَارَ يَهُودَ عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم، وَوَصَفَا لَهُمْ أَمْرَهُ، وَأَخْبَرَاهُمْ بِبَعْضِ قَوْلِهِ، وَقَالَا لَهُمْ: إنَّكُمْ أَهْلُ التَّوْرَاةِ، وَقَدْ جِئْنَاكُمْ لِتُخْبِرُونَا عَنْ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص300 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '24', num: 24, category: 'makkah', icon: '🕋', title: 'إسلام الطفيل', location: 'مكة المكرمة', date: 'العهد المكي', summary: 'سمع القرآن فأسلم ودعا قومه في دوس.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=24', history: 'كان الطفيل بن عمرو الدوسي سيدًا مطاعًا في قبيلته دوس وشاعرًا لبيبًا. فلما قدم مكة مشى إليه رجال من قريش يحذّرونه من النبي ﷺ ويقولون: إن قوله كالسحر يفرّق بين الرجل وأبيه وأخيه وزوجته، فلا تكلّمه ولا تسمع منه. فما زالوا به، كما يروي ابن إسحاق، حتى حشا أذنيه قطنًا خشية أن يبلغه شيء من قوله.\n\nثم غدا إلى المسجد فإذا رسول الله ﷺ قائم يصلي عند الكعبة، فأبى الله إلا أن يُسمعه بعض قوله، فسمع كلامًا حسنًا. فقال في نفسه: إني لرجل لبيب شاعر ما يخفى عليّ الحسن من القبيح، فما يمنعني أن أسمع؟ فتبعه إلى بيته وسمع منه القرآن، فأسلم. ثم رجع إلى قومه داعيًا، فأسلم أبوه وزوجته وأبطأت عليه دوس. فجاء يشكوهم، فدعا لهم النبي ﷺ كما في الصحيحين: «اللهم اهدِ دوسًا وأتِ بهم». فعاد يدعوهم برفق حتى قدم بسبعين أو ثمانين بيتًا منهم والنبي ﷺ بخيبر، وفيهم أبو هريرة. واستُشهد الطفيل يوم اليمامة.', details: '<p class="summary-text">حذّرته قريش من سماع النبي ﷺ فحشا أذنيه قطنًا، ثم سمع القرآن فأسلم ودعا قومه.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: وَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم، عَلَى مَا يَرَى مِنْ قَوْمِهِ، يَبْذُلُ لَهُمْ النَّصِيحَةَ، وَيَدْعُوهُمْ إلَى النَّجَاةِ مِمَّا هُمْ فِيهِ. وَجَعَلَتْ قُرَيْشٌ، حِينَ مَنَعَهُ اللَّهُ مِنْهُمْ، يُحَذِّرُونَهُ النَّاسَ وَمَنْ قَدِمَ عَلَيْهِمْ مِنْ الْعَرَبِ. وَكَانَ الطُّفَيْلُ بْنُ عَمْرٍو الدَّوْسِيُّ يُحَدِّثُ: أَنَّهُ قَدِمَ مَكَّةَ وَرَسُولُ اللَّهِ صلى الله عليه وسلم بِهَا، فَمَشَى إلَيْهِ رِجَالٌ مِنْ قُرَيْشٍ، وَكَانَ الطُّفَيْلُ رَجُلًا شَرِيفًا شَاعِرًا لَبِيبًا، فَقَالُوا لَهُ: يَا طُفَيْلُ، إنَّكَ قَدِمْتَ بِلَادَنَا، وَهَذَا الرَّجُلُ الَّذِي بَيْنَ أَظْهُرِنَا …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص382 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '25', num: 25, category: 'makkah', icon: '🛡️', title: 'حصار الشعب', location: 'شعب أبي طالب', date: '616 - 619م', summary: 'مقاطعة قريش لبني هاشم وحصارهم في الشعب.', lat: 21.4245, lng: 39.8275, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=25', history: 'لما رأت قريش أن الإسلام يفشو، وأن بني هاشم وبني المطلب، مسلمهم وكافرهم، قد اجتمعوا على حماية النبي ﷺ، تعاقدت على مقاطعتهم: ألا يناكحوهم ولا يبايعوهم ولا يجالسوهم حتى يسلّموا رسول الله ﷺ للقتل. وكتبوا بذلك صحيفة علّقوها في جوف الكعبة، وكان ذلك في المحرم من السنة السابعة للبعثة. فانحاز بنو هاشم وبنو المطلب إلى شعب أبي طالب، إلا أبا لهب فإنه ظاهر قريشًا.\n\nاستمر الحصار نحو ثلاث سنين، اشتد فيها الجهد حتى أكلوا ورق الشجر، وكان يُسمع من وراء الشعب بكاء صبيانهم من الجوع. وكان لا يصل إليهم شيء إلا سرًّا، ممن أراد صلتهم من قريش كحكيم بن حزام وهشام بن عمرو. ثم سعى في نقض الصحيفة خمسة من أهل المروءة: هشام بن عمرو، وزهير بن أبي أمية، والمطعم بن عدي، وأبو البختري بن هشام، وزمعة بن الأسود. فلما قام المطعم ليشقّها وجد الأرَضة قد أكلتها إلا «باسمك اللهم»، فخرج المحاصَرون من الشعب.', details: '<p class="summary-text">كتبت قريش صحيفة بمقاطعة بني هاشم وبني المطلب، فحوصروا في الشعب حتى أكلوا ورق الشجر.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: فَلَمَّا رَأَتْ قُرَيْشٌ أَنَّ أَصْحَابَ رَسُولِ اللَّهِ صلى الله عليه وسلم قَدْ نَزَلُوا بَلَدًا أَصَابُوا بِهِ أَمْنًا وَقَرَارًا، وَأَنَّ النَّجَاشِيَّ قَدْ مَنَعَ مَنْ لَجَأَ إلَيْهِ مِنْهُمْ، وَأَنَّ عُمَرَ قَدْ أَسْلَمَ، فَكَانَ هُوَ وَحَمْزَةُ بْنُ عَبْدِ الْمُطَّلِبِ مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم وَأَصْحَابِهِ، وَجَعَلَ الْإِسْلَامُ يَفْشُو فِي الْقَبَائِلِ، اجْتَمَعُوا وَائْتَمَرُوا (بَيْنَهُمْ) أَنْ يَكْتُبُوا كِتَابًا يَتَعَاقَدُونَ فِيهِ عَلَى بَنِي هَاشِمٍ، وَبَنِيَّ الْمُطَّلِبِ، عَلَى أَنْ لَا يُنْكِحُوا إلَيْهِمْ وَلَا يُنْكَحُوهُمْ، وَلَا يَبِيعُوهُمْ شَيْئًا …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص350 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '26', num: 26, category: 'makkah', icon: '🕋', title: 'عام الحزن', location: 'مكة المكرمة', date: '619م', summary: 'وفاة أبي طالب ثم خديجة رضي الله عنها.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=26', history: 'في السنة العاشرة للبعثة، وبعد الخروج من الشعب بقليل، توفي أبو طالب الذي حمى النبي ﷺ ودافع عنه أكثر من أربعين سنة. وفي الصحيحين أن النبي ﷺ دخل عليه وهو يحتضر وعنده أبو جهل وعبد الله بن أبي أمية، فقال: «يا عم، قل لا إله إلا الله، كلمة أحاجّ لك بها عند الله». فقالا: أترغب عن ملة عبد المطلب؟ فكان آخر ما قال أنه على ملة عبد المطلب. وفيه نزل قوله تعالى: «إنك لا تهدي من أحببت ولكن الله يهدي من يشاء».\n\nثم توفيت خديجة رضي الله عنها بعده بمدة يسيرة، في رمضان على المشهور، ودُفنت بالحَجون. وهي التي آمنت به حين كفر الناس، وواسته بمالها، وفي الصحيحين أن جبريل بشّرها ببيت في الجنة من قصب لا صخب فيه ولا نصب. فاجتمع على النبي ﷺ فقد الحامي خارج البيت والسند داخله، واجترأت عليه قريش بما لم تكن تطمع فيه من قبل، حتى سمّى أهل السير هذا العام «عام الحزن».', details: '<p class="summary-text">توفي أبو طالب ثم خديجة بعد الخروج من الشعب بقليل، ففقد النبي ﷺ الحامي والسند.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: وَكَانَ النَّفَرُ الَّذِينَ يُؤْذُونَ رَسُولَ اللَّهِ صلى الله عليه وسلم فِي بَيْتِهِ: أَبَا لَهَبٍ، وَالْحَكَمَ بْنَ الْعَاصِ بْنِ أُمَيَّةَ، وَعُقْبَةَ بْنَ أَبِي مُعَيْطٍ، وَعَدِيَّ بْنَ حَمْرَاءَ الثَّقَفِيَّ، وَابْنَ الْأَصْدَاءِ الْهُذَلِيَّ، وَكَانُوا جِيرَانَهُ لَمْ يُسْلِمْ مِنْهُمْ أَحَدٌ إلَّا الْحَكَمُ بْنُ أَبِي الْعَاصِ، فَكَانَ أَحَدُهُمْ- فِيمَا ذُكِرَ لِي- يَطْرَحُ عَلَيْهِ صلى الله عليه وسلم رَحِمَ الشَّاةِ وَهُوَ يُصَلِّي، وَكَانَ أَحَدُهُمْ يَطْرَحُهَا فِي بُرْمَتِهِ إذَا نُصِبَتْ لَهُ، حَتَّى اتَّخَذَ رَسُولُ اللَّهِ صلى الله عليه وسلم حِجْرًا يَسْتَتِرُ بِهِ مِنْهُمْ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص415 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '27', num: 27, category: 'hijra', icon: '🗺️', title: 'رحلة الطائف', location: 'الطائف', date: '619م', summary: 'خرج يلتمس النصرة فردوه وأغروا به سفهاءهم.', lat: 21.2643, lng: 40.4022, image: 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=27', history: 'بعد وفاة أبي طالب اشتد أذى قريش، فخرج النبي ﷺ في شوال من السنة العاشرة للبعثة إلى الطائف، ومعه مولاه زيد بن حارثة، يلتمس النصرة من ثقيف. فقصد سادتها الثلاثة من بني عمرو بن عمير، فردّوا عليه ردًّا قبيحًا، وأغروا به سفهاءهم وعبيدهم يسبّونه ويرمونه بالحجارة حتى أدموا قدميه. فالتجأ إلى بستان لعتبة وشيبة ابني ربيعة، وهناك يروي ابن إسحاق دعاءه المشهور: «اللهم إليك أشكو ضعف قوتي، وقلة حيلتي، وهواني على الناس... إن لم يكن بك عليّ غضب فلا أبالي».\n\nوأرسل إليه ابنا ربيعة غلامهما عدّاسًا النصراني بقِطف من عنب، فلما سمعه يسمّي الله وعرف أنه نبي أكبّ عليه يقبّل رأسه ويديه. وفي الصحيحين أن ملك الجبال أتاه عند قرن الثعالب يستأذنه أن يطبق على أهل مكة الأخشبين، فقال ﷺ: «بل أرجو أن يُخرج الله من أصلابهم من يعبد الله وحده لا يشرك به شيئًا». ثم عاد إلى مكة فدخلها في جوار المطعم بن عدي.', details: '<p class="summary-text">خرج النبي ﷺ إلى ثقيف يلتمس النصرة، فردّوه وأغروا به سفهاءهم، فعاد إلى مكة في جوار المطعم بن عدي.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: وَلَمَّا هَلَكَ أَبُو طَالِبٍ نَالَتْ قُرَيْشٌ مِنْ رَسُولِ اللَّهِ صلى الله عليه وسلم مِنْ الْأَذَى مَا لَمْ تَكُنْ تَنَالُ مِنْهُ فِي حَيَاةِ عَمِّهِ أَبِي طَالِبٍ، فَخَرَجَ رَسُولُ اللَّهِ صلى الله عليه وسلم إلَى الطَّائِفِ، يَلْتَمِسُ النُّصْرَةَ مِنْ ثَقِيفٍ، وَالْمَنَعَةَ بِهِمْ مِنْ قَوْمِهِ، وَرَجَاءَ أَنْ يَقْبَلُوا مِنْهُ مَا جَاءَهُمْ بِهِ مِنْ اللَّهِ عز وجل، فَخَرَجَ إلَيْهِمْ وَحْدَهُ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص419 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '28', num: 28, category: 'makkah', icon: '🏛️', title: 'وفد الجن', location: 'بطن نخلة', date: '619م', summary: 'استمع نفر من الجن للقرآن فآمنوا.', lat: 21.6000, lng: 40.0000, image: 'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=28', history: 'في طريق عودته من الطائف نزل النبي ﷺ بوادي نخلة بين الطائف ومكة، فقام من جوف الليل يصلي ويقرأ القرآن. فصرف الله إليه نفرًا من الجن، يذكر ابن إسحاق أنهم سبعة من جن نصيبين، فاستمعوا لتلاوته وهو لا يشعر بهم، فلما فرغ ولّوا إلى قومهم منذرين وقد آمنوا وأجابوا.\n\nوقد قصّ القرآن خبرهم في قوله تعالى: «وإذ صرفنا إليك نفرًا من الجن يستمعون القرآن فلما حضروه قالوا أنصتوا فلما قُضي ولّوا إلى قومهم منذرين»، وفي سورة الجن: «قل أوحي إليّ أنه استمع نفر من الجن فقالوا إنا سمعنا قرآنًا عجبًا، يهدي إلى الرشد فآمنا به». وفي الصحيحين عن ابن عباس ذكر استماع الجن لقراءته ﷺ بنخلة وهو يصلي بأصحابه الفجر، وللعلماء كلام في كون ذلك واقعة واحدة أو أكثر. وكان في هذا الحدث تسلية للنبي ﷺ بعد ما لقيه من أهل الطائف: إن أعرض عنه بعض الإنس فقد آمن به غيرهم من خلق الله.', details: '<p class="summary-text">في طريق العودة من الطائف قام النبي ﷺ يصلي بنخلة، فاستمع إليه نفر من الجن فآمنوا.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ: ثُمَّ إنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم انْصَرَفَ مِنْ الطَّائِفِ رَاجِعًا إلَى مَكَّةَ، حِينَ يَئِسَ مِنْ خَيْرِ ثَقِيفٍ، حَتَّى إذَا كَانَ بِنَخْلَةَ قَامَ مِنْ جَوْفِ اللَّيْلِ يُصَلِّي، فَمَرَّ بِهِ النَّفَرُ مِنْ الْجِنِّ الَّذِينَ ذَكَرَهُمْ اللَّهُ تبارك وتعالى، وَهُمْ- فِيمَا ذُكِرَ لِي- سَبْعَةُ نَفَرٍ مِنْ جِنِّ أَهْلِ نَصِيبِينَ ، فَاسْتَمَعُوا لَهُ، فَلَمَّا فَرَغَ مِنْ صَلَاتِهِ وَلَّوْا إلَى قَوْمِهِمْ مُنْذِرِينَ، قَدْ آمَنُوا وَأَجَابُوا إلَى مَا سَمِعُوا.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص421 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '29', num: 29, category: 'makkah', icon: '🏛️', title: 'عرض الدعوة', location: 'منى وعكاظ', date: '619 - 621م', summary: 'يتبع القبائل في المواسم بحثاً عن النصرة.', lat: 21.4133, lng: 39.8933, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=29', history: 'بعد أن أُغلقت أبواب مكة والطائف، جعل النبي ﷺ يعرض نفسه على قبائل العرب في مواسم الحج وأسواقها: عكاظ ومجنة وذي المجاز، ثم في منازلهم بمنى. يأتي القبيلة فيدعوها إلى الله، ويسألها أن تؤويه وتمنعه حتى يبلّغ رسالة ربه. وفي حديث جابر عند الإمام أحمد أنه كان يقول: «من يؤويني؟ من ينصرني حتى أبلّغ رسالة ربي وله الجنة؟». وكان عمه أبو لهب يمشي خلفه يقول: لا تطيعوه فإنه صابئ كذّاب.\n\nعرض ﷺ نفسه على كندة وكلب وبني حنيفة وبني عامر بن صعصعة وغيرهم، فمنهم من ردّ ردًّا قبيحًا، ومنهم من اشترط أن يكون له الأمر من بعده، فقال ﷺ: «الأمر إلى الله يضعه حيث يشاء». وبقي على ذلك سنين لا ييأس. حتى لقي في موسم السنة الحادية عشرة للبعثة عند العقبة بمنى ستة نفر من الخزرج من أهل يثرب، فيهم أسعد بن زرارة، فدعاهم فأسلموا، وعادوا إلى قومهم بخبره، فكانوا بداية الفرج.', details: '<p class="summary-text">كان النبي ﷺ يتبع القبائل في منازلها بعكاظ ومجنة ومنى يقول: من يؤويني؟ من ينصرني؟</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: ثُمَّ قَدِمَ رَسُولُ اللَّهِ صلى الله عليه وسلم مَكَّةَ، وَقَوْمُهُ أَشَدُّ مَا كَانُوا عَلَيْهِ مِنْ خِلَافِهِ وَفِرَاقِ دِينِهِ، إلَّا قَلِيلًا مُسْتَضْعَفِينَ، مِمَّن آمن بِهِ. فَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَعْرِضُ نَفْسَهُ فِي الْمَوَاسِمِ، إذَا كَانَتْ، عَلَى قَبَائِلِ الْعَرَبِ يَدْعُوهُمْ إلَى اللَّهِ، وَيُخْبِرُهُمْ أَنَّهُ نَبِيٌّ مُرْسَلٌ، وَيَسْأَلُهُمْ أَنْ يُصَدِّقُوهُ وَيَمْنَعُوهُ حَتَّى يُبَيِّنَ (لَهُمْ) اللَّهُ مَا بَعَثَهُ بِهِ .\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص422 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '30', num: 30, category: 'hijra', icon: '🕌', title: 'الإسراء والمعراج', location: 'المسجد الأقصى', date: 'نحو 621م', summary: 'أُسري به ليلًا وفرضت الصلوات الخمس.', lat: 31.7761, lng: 35.2358, image: 'https://images.unsplash.com/photo-1580418827493-f2b22c0a76cb?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=30', history: 'بعد عام الحزن ورحلة الطائف أكرم الله نبيه ﷺ برحلة الإسراء والمعراج. قال تعالى: «سبحان الذي أسرى بعبده ليلًا من المسجد الحرام إلى المسجد الأقصى الذي باركنا حوله لنريه من آياتنا». وقد اختلف أهل السير في تاريخها، والمشهور أنها كانت قبل الهجرة بنحو سنة. أُسري به ﷺ على البراق من مكة إلى بيت المقدس، فصلى هناك بالأنبياء إمامًا، ثم عُرج به إلى السماوات.\n\nوفي الصحيحين أنه لقي في السماوات آدم، ثم يحيى وعيسى، ثم يوسف، ثم إدريس، ثم هارون، ثم موسى، ثم إبراهيم عليهم السلام، ثم رُفع إلى سدرة المنتهى. وهناك فُرضت الصلاة خمسين صلاة، فما زال يراجع ربه بمشورة موسى عليه السلام حتى صارت خمسًا في العمل وخمسين في الأجر. فلما أصبح أخبر قريشًا فكذّبوه واستعظموا الأمر، فوصف لهم بيت المقدس وصفًا دقيقًا. وأما أبو بكر فقال: «إن كان قال فقد صدق»، فلُقّب بالصدّيق.', details: '<p class="summary-text">أُسري بالنبي ﷺ ليلًا من المسجد الحرام إلى المسجد الأقصى، ثم عُرج به إلى السماوات العلى وفُرضت الصلاة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ هِشَامٍ: حَدَّثَنَا زِيَادُ بْنُ عَبْدِ اللَّهِ الْبَكَّائِيُّ عَنْ مُحَمَّدِ بْنِ إسْحَاقَ الْمُطَّلِبِيِّ قَالَ: ثُمَّ أُسْرِيَ بِرَسُولِ اللَّهِ صلى الله عليه وسلم مِنْ الْمَسْجِدِ الْحَرَامِ إلَى الْمَسْجِدِ الْأَقْصَى، وَهُوَ بَيْتُ الْمَقْدِسِ مِنْ إيلِيَاء ، وَقَدْ فَشَا الْإِسْلَامُ بِمَكَّةَ فِي قُرَيْشٍ، وَفِي الْقَبَائِلِ كُلِّهَا.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص396 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '31', num: 31, category: 'makkah', icon: '🏛️', title: 'العقبة الأولى', location: 'منى', date: '621م', summary: 'بايعه 12 رجلاً من يثرب وأرسل مصعب معلماً.', lat: 21.4133, lng: 39.8933, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=31', history: 'في موسم الحج من السنة الثانية عشرة للبعثة، نحو سنة 621م، وافى مكة اثنا عشر رجلًا من أهل يثرب: عشرة من الخزرج واثنان من الأوس، وفيهم خمسة من الستة الذين أسلموا في العام السابق. فلقوا النبي ﷺ عند العقبة بمنى وبايعوه. روى البخاري ومسلم عن عبادة بن الصامت، وكان منهم، أن رسول الله ﷺ قال: «بايعوني على ألا تشركوا بالله شيئًا، ولا تسرقوا، ولا تزنوا، ولا تقتلوا أولادكم، ولا تأتوا ببهتان تفترونه بين أيديكم وأرجلكم، ولا تعصوا في معروف».\n\nفلما انصرفوا بعث معهم مصعب بن عمير يقرئهم القرآن ويعلّمهم الإسلام، فنزل على أسعد بن زرارة، وكان يُسمى بالمدينة «المقرئ». وبحكمته ولينه أسلم على يديه سيدا بني عبد الأشهل: أُسيد بن حُضير وسعد بن معاذ، فأسلم بإسلامهما قومهما في يوم واحد. ولم تمضِ سنة حتى لم تبقَ دار من دور الأنصار إلا وفيها رجال ونساء مسلمون، فتهيأت يثرب لتكون دار الهجرة.', details: '<p class="summary-text">بايع اثنا عشر رجلًا من أهل يثرب النبي ﷺ عند العقبة، وأرسل معهم مصعب بن عمير معلمًا.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  حَتَّى إذَا كَانَ الْعَامُ الْمُقْبِلُ وَافَى الْمَوْسِمَ مِنْ الْأَنْصَارِ اثْنَا عَشَرَ رَجُلًا، فَلَقَوْهُ بِالْعَقَبَةِ. (قَالَ) : وَهِيَ الْعَقَبَةُ الْأُولَى، فَبَايَعُوا رَسُولَ اللَّهِ صلى الله عليه وسلم عَلَى بَيْعَةِ النِّسَاءِ ، وَذَلِكَ قَبْلَ أَنْ تُفْتَرَضَ عَلَيْهِمْ الْحَرْبُ. مِنْهُمْ مِنْ بَنِي النَّجَّارِ، ثُمَّ مِنْ بَنِي مَالِكِ بْنِ النَّجَّارِ: أَسْعَدُ بْنُ زُرَارَةَ بْنِ عُدَسَ بْنِ عُبَيْدِ بْنِ ثَعْلَبَةَ بْنِ غَنْمِ بْنِ مَالِكِ بْنِ النَّجَّارِ، وَهُوَ أَبُو أُمَامَةَ، وَعَوْفٌ، وَمُعَاذٌ، ابْنَا الْحَارِثِ بْنِ رِفَاعَةَ بْنِ سَوَادِ بْنِ مَالِكِ بْنِ غَنْمِ بْنِ مَالِكِ بْنِ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص431 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '32', num: 32, category: 'makkah', icon: '🏛️', title: 'العقبة الثانية', location: 'منى', date: '622م', summary: 'بايعه 70 من الأنصار على النصرة والمنعة.', lat: 21.4133, lng: 39.8933, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=32', history: 'في موسم الحج من السنة الثالثة عشرة للبعثة، سنة 622م، خرج من يثرب ثلاثة وسبعون رجلًا وامرأتان من المسلمين مع حجاج قومهم، وواعدوا النبي ﷺ العقبة أوسط أيام التشريق. فتسللوا في جوف الليل، وجاء النبي ﷺ ومعه عمه العباس بن عبد المطلب، وكان يومئذ على دين قومه، فأراد أن يتوثق لابن أخيه. وكانت المرأتان نسيبة بنت كعب أم عمارة، وأسماء بنت عمرو.\n\nبايعوه على السمع والطاعة في النشاط والكسل، والنفقة في العسر واليسر، والأمر بالمعروف والنهي عن المنكر، وعلى أن ينصروه إذا قدم عليهم ويمنعوه مما يمنعون منه أنفسهم وأزواجهم وأبناءهم، ولهم الجنة. وسألوه: فهل عسيت إن أظهرك الله أن ترجع إلى قومك وتدعنا؟ فتبسّم وقال: «بل الدم الدم والهدم الهدم، أنا منكم وأنتم مني». ثم اختار منهم اثني عشر نقيبًا: تسعة من الخزرج وثلاثة من الأوس. وبعد هذه البيعة أذن النبي ﷺ لأصحابه بالهجرة إلى المدينة، فخرجوا أرسالًا.', details: '<p class="summary-text">بايع نحو سبعين من الأنصار النبي ﷺ على النصرة والمنعة، فمهّدت البيعة للهجرة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ: فَتَكَلَّمَ رَسُولُ اللَّهِ صلى الله عليه وسلم، فَتَلَا الْقُرْآنَ، وَدَعَا إلَى اللَّهِ، وَرَغَّبَ فِي الْإِسْلَامِ، ثُمَّ قَالَ أُبَايِعُكُمْ عَلَى أَنْ تَمْنَعُونِي مِمَّا تَمْنَعُونَ مِنْهُ نِسَاءَكُمْ وَأَبْنَاءَكُمْ. قَالَ: فَأَخَذَ الْبَرَاءُ بْنُ مَعْرُورٍ بِيَدِهِ، ثُمَّ قَالَ: نَعَمْ، وَاَلَّذِي بَعَثَكَ بِالْحَقِّ (نَبِيًّا) ، لَنَمْنَعَنَّكَ مِمَّا نَمْنَعُ مِنْهُ أُزُرَنَا ، فَبَايِعْنَا يَا رَسُولَ اللَّهِ، فَنَحْنُ وَاَللَّهِ أَبْنَاءُ الْحُرُوبِ، وَأَهْلُ الْحَلْقَةِ ، وَرِثْنَاهَا كَابِرًا (عَنْ كَابِرٍ) .\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص442 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '33', num: 33, category: 'hijra', icon: '🕌', title: 'الهجرة النبوية', location: 'المدينة المنورة', date: '622م', summary: 'وصوله للمدينة وتأسيس الدولة الإسلامية.', lat: 24.4672, lng: 39.6112, image: 'https://images.unsplash.com/photo-1580418827493-f2b22c0a76cb?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=33', history: 'لما هاجر أكثر الصحابة إلى يثرب اجتمع زعماء قريش في دار الندوة، وأجمعوا أن يأخذوا من كل قبيلة فتى فيضربوا النبي ﷺ ضربة رجل واحد ليتفرق دمه في القبائل. قال تعالى: «وإذ يمكر بك الذين كفروا ليثبتوك أو يقتلوك أو يخرجوك». فأذن الله لنبيه بالهجرة، فخرج ليلًا وترك عليًّا في فراشه ليردّ الودائع إلى أهلها. وسار مع أبي بكر الصديق إلى غار ثور جنوب مكة، فمكثا فيه ثلاث ليال، يأتيهما عبد الله بن أبي بكر بالأخبار، وأسماء ذات النطاقين بالطعام، وعامر بن فهيرة بالغنم يعفّي الأثر. وبلغ المشركون فم الغار، فقال ﷺ لصاحبه: «ما ظنك باثنين الله ثالثهما؟».\n\nثم سلكا طريق الساحل مع الدليل عبد الله بن أريقط، ولحق بهما سراقة بن مالك طمعًا في الجائزة فساخت قوائم فرسه، فرجع يصرف عنهما الطلب. ووصل ﷺ قباء يوم الاثنين من ربيع الأول، في سبتمبر 622م، فأسّس مسجدها، ثم دخل المدينة والناس يستقبلونه، ونزل في دار أبي أيوب الأنصاري. وبهذه الهجرة أرّخ المسلمون تقويمهم في خلافة عمر.', details: '<p class="summary-text">خرج النبي ﷺ مع أبي بكر سرًّا، فمكثا في غار ثور ثلاثًا، ثم سلكا طريق الساحل حتى بلغا قباء ثم المدينة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  فَأَتَى جِبْرِيلُ عليه السلام رَسُولَ اللَّهِ صلى الله عليه وسلم، فَقَالَ: لَا تَبِتْ هَذِهِ اللَّيْلَةَ عَلَى فِرَاشِكَ الَّذِي كُنْتَ تَبِيتُ عَلَيْهِ. قَالَ: فَلَمَّا كَانَتْ عَتَمَةٌ مِنْ اللَّيْلِ اجْتَمَعُوا عَلَى بَابِهِ يَرْصُدُونَهُ مَتَى يَنَامُ، فَيَثِبُونَ عَلَيْهِ، فَلَمَّا رَأَى رَسُولُ اللَّهِ صلى الله عليه وسلم مَكَانَهُمْ، قَالَ لِعَلِيِّ بْنِ أَبِي طَالِبٍ: نَمْ عَلَى فِرَاشِي وَتَسَجَّ بِبُرْدِي هَذَا الْحَضْرَمِيِّ الْأَخْضَرِ، فَنَمْ فِيهِ، فَإِنَّهُ لَنْ يَخْلُصَ إلَيْكَ شَيْءٌ تَكْرَهُهُ مِنْهُمْ، وَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَنَامُ فِي بُرْدِهِ ذَلِكَ إذَا نَامَ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص482 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '34', num: 34, category: 'madinah', icon: '🕌', title: 'بناء المسجد', location: 'المدينة المنورة', date: '622 - 623م', summary: 'بناء المسجد والمؤاخاة ووثيقة المدينة.', lat: 24.4672, lng: 39.6112, image: 'https://images.unsplash.com/photo-1580418827493-f2b22c0a76cb?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=34', history: 'كان أول ما بدأ به النبي ﷺ في المدينة بناء المسجد، في الموضع الذي بركت فيه ناقته. وكانت الأرض مِربدًا لغلامين يتيمين من بني النجار، سهل وسهيل، فاشتراها منهما. وبُني المسجد باللبِن، وجُعلت أعمدته من جذوع النخل وسقفه من الجريد، وعمل النبي ﷺ فيه بيده مع أصحابه وهم يرتجزون: «اللهم لا عيش إلا عيش الآخرة، فاغفر للأنصار والمهاجرة». وبُنيت بجواره حجرات أزواجه، وكانت الصُّفّة في مؤخرته مأوى لفقراء المهاجرين. فكان المسجد موضع الصلاة والتعليم والشورى وإدارة شؤون الناس.\n\nثم آخى ﷺ بين المهاجرين والأنصار مؤاخاة ضربت أروع أمثلة الإيثار، حتى عرض سعد بن الربيع على عبد الرحمن بن عوف نصف ماله، فقال: بارك الله لك في أهلك ومالك، دلّوني على السوق. وكتب ﷺ وثيقة المدينة تنظّم العلاقة بين المسلمين وسائر أهلها ومنهم اليهود: أن المؤمنين أمة واحدة، وأن لليهود دينهم وللمسلمين دينهم، وأن بينهم النصر على من دهم يثرب، وأن المرجع عند الخلاف إلى الله ورسوله.', details: '<p class="summary-text">بنى النبي ﷺ المسجد، وآخى بين المهاجرين والأنصار، وكتب وثيقة تنظم العلاقات في المدينة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ: فَأَمَرَ بِهِ رَسُولُ اللَّهِ صلى الله عليه وسلم أَنْ يُبْنَى مَسْجِدًا، وَنَزَلَ رَسُولُ اللَّهِ صلى الله عليه وسلم عَلَى أَبِي أَيُّوبَ حَتَّى بَنَى مَسْجِدَهُ وَمَسَاكِنَهُ، فَعَمِلَ فِيهِ رَسُولُ اللَّهِ صلى الله عليه وسلم لِيُرَغِّبَ الْمُسْلِمِينَ فِي الْعَمَلِ فِيهِ، فَعَمِلَ فِيهِ الْمُهَاجِرُونَ وَالْأَنْصَارُ، وَدَأَبُوا فِيهِ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص496 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '35', num: 35, category: 'madinah', icon: '🕌', title: 'تحويل القبلة', location: 'مسجد القبلتين', date: '624م', summary: 'الأمر بالتوجه نحو الكعبة بدلاً من الأقصى.', lat: 24.4839, lng: 39.5816, image: 'https://images.unsplash.com/photo-1580418827493-f2b22c0a76cb?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=35', history: 'كان النبي ﷺ يصلي في مكة ثم في المدينة مستقبلًا بيت المقدس، وكان يحب أن يُوجَّه إلى الكعبة قبلة أبيه إبراهيم، فكان يقلّب وجهه في السماء. روى البخاري ومسلم عن البراء بن عازب أنه ﷺ صلى نحو بيت المقدس ستة عشر أو سبعة عشر شهرًا بعد الهجرة. ثم نزل في السنة الثانية للهجرة، في رجب أو شعبان على خلاف، قوله تعالى: «قد نرى تقلّب وجهك في السماء فلنولّينّك قبلة ترضاها فولِّ وجهك شطر المسجد الحرام».\n\nويُروى أن الأمر نزل والنبي ﷺ يصلي بأصحابه في مسجد بني سلِمة، فاستدار في صلاته نحو الكعبة، فعُرف المسجد بمسجد القبلتين. وبلغ الخبر أهل قباء وهم في صلاة الصبح، فاستداروا وهم ركوع كما في الصحيحين. وكان التحويل امتحانًا للقلوب، فقال اليهود والمنافقون: ما ولّاهم عن قبلتهم؟ فردّ القرآن: «قل لله المشرق والمغرب». وسأل الناس عمّن مات قبل التحويل، فنزل: «وما كان الله ليضيع إيمانكم». وبه تميّزت الأمة بقبلتها.', details: '<p class="summary-text">بعد نحو ستة عشر أو سبعة عشر شهرًا من الصلاة نحو بيت المقدس، أُمر المسلمون بالتوجه إلى الكعبة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: وَيُقَالُ: صُرِفَتْ الْقِبْلَةُ فِي شَعْبَانَ عَلَى رَأْسِ ثَمَانِيَةَ عَشَرَ شَهْرًا مِنْ مَقْدَمِ رَسُولِ اللَّهِ صلى الله عليه وسلم الْمَدِينَةَ .\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص606 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '36', num: 36, category: 'madinah', icon: '⚔', title: 'غزوة بدر', location: 'بدر', date: '624م', summary: 'يوم الفرقان ونصر المسلمين الحاسم.', lat: 23.7744, lng: 38.7891, image: 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=36', history: 'في رمضان من السنة الثانية للهجرة، مارس 624م، خرج النبي ﷺ في ثلاثمئة وبضعة عشر رجلًا، معهم فَرَسان وسبعون بعيرًا يتعاقبون عليها، يريدون قافلة لقريش عائدة من الشام بقيادة أبي سفيان، وكانت قريش قد استولت على أموال المهاجرين بمكة. فنجا أبو سفيان بالقافلة عن طريق الساحل، لكن قريشًا خرجت في نحو ألف مقاتل وأصرّ أبو جهل على القتال. فاستشار النبي ﷺ أصحابه، فتكلم المقداد بن عمرو عن المهاجرين، ثم قال سعد بن معاذ عن الأنصار: «لو استعرضت بنا هذا البحر فخضته لخضناه معك».\n\nونزل المسلمون عند ماء بدر بمشورة الحُباب بن المنذر، وبات النبي ﷺ يدعو ربه: «اللهم إن تهلك هذه العصابة لا تُعبد في الأرض». والتقى الجمعان صبيحة السابع عشر من رمضان، وأمدّ الله المؤمنين بالملائكة، فانتهت المعركة بنصر حاسم: قُتل سبعون من المشركين فيهم أبو جهل وأمية بن خلف، وأُسر سبعون، واستُشهد أربعة عشر من المسلمين. وجُعل فداء بعض الأسرى أن يعلّم عشرة من أبناء المدينة الكتابة. وسمّاه القرآن «يوم الفرقان».', details: '<p class="summary-text">التقى نحو ثلاثمئة وبضعة عشر مسلمًا بنحو ألف من قريش، فكان يوم الفرقان ونصرًا حاسمًا.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: ثُمَّ إنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم سَمِعَ بِأَبِي سُفْيَانَ بْنِ حَرْبٍ مُقْبِلًا مِنْ الشَّأْمِ فِي عِيرٍ لِقُرَيْشٍ عَظِيمَةٍ، فِيهَا أَمْوَالٌ لِقُرَيْشِ وَتِجَارَةٌ مِنْ تِجَارَاتِهِمْ وَفِيهَا ثَلَاثُونَ رَجُلًا مِنْ قُرَيْشٍ أَوْ أَرْبَعُونَ، مِنْهُمْ مَخْرَمَةُ بْنُ نَوْفَلِ بْنُ أُهَيْبِ بْنِ عَبْدِ مَنَافِ بْنِ زُهْرَةَ، وَعَمْرُو بْنُ الْعَاصِ بْنِ وَائِلِ بْنِ هِشَامٍ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص606 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '37', num: 37, category: 'madinah', icon: '⚔', title: 'غزوة أحد', location: 'جبل أحد', date: '625م', summary: 'معركة أحد واستشهاد حمزة رضي الله عنه.', lat: 24.5036, lng: 39.6116, image: 'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=37', history: 'في شوال من السنة الثالثة للهجرة، مارس 625م، زحفت قريش في ثلاثة آلاف مقاتل بقيادة أبي سفيان تطلب الثأر لقتلى بدر. فاستشار النبي ﷺ أصحابه، ثم خرج في نحو ألف، فانخذل رأس المنافقين عبد الله بن أُبيّ بثلث الجيش في الطريق. ونزل المسلمون بسفح جبل أحد شمال المدينة وجعلوا ظهورهم إليه، وأقام النبي ﷺ خمسين راميًا على جبل صغير بقيادة عبد الله بن جبير، وأمرهم ألا يبرحوا مكانهم سواء كان النصر أو الهزيمة.\n\nكانت الغلبة للمسلمين أول النهار وولّى المشركون، فظنّ أكثر الرماة أن المعركة انتهت فنزلوا يطلبون الغنيمة. فانتهز خالد بن الوليد الثغرة والتفّ بالفرسان من الخلف، فاضطرب الصف، وشاع أن النبي ﷺ قُتل، وقد شُجّ وجهه وكُسرت رباعيته وثبتت معه قلة من أصحابه يفدونه بأنفسهم. واستُشهد نحو سبعين، فيهم حمزة بن عبد المطلب ومصعب بن عمير وأنس بن النضر. ونزلت آيات آل عمران تعزّي وتربّي: «ولا تهنوا ولا تحزنوا وأنتم الأعلون إن كنتم مؤمنين». وبقي درس أحد شاهدًا على أثر مخالفة الأمر.', details: '<p class="summary-text">جاءت قريش تطلب الثأر لبدر، وكان النصر للمسلمين أولًا، ثم تحول حين ترك الرماة مواقعهم.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  لَمَّا أُصِيبَ يَوْمَ بَدْرٍ مِنْ كُفَّارِ قُرَيْشٍ أَصْحَابِ الْقَلِيبِ، وَرَجَعَ فَلُّهُمْ إلَى مَكَّةَ، وَرَجَعَ أَبُو سُفْيَانَ بْنُ حَرْبٍ بِعِيرِهِ، مَشَى عَبْدُ اللَّهِ بْنُ أَبِي رَبِيعَةَ، وَعِكْرِمَةُ بْنُ أَبِي جَهْلٍ، وَصَفْوَانُ بْنُ أُمَيَّةَ، فِي رِجَالٍ مِنْ قُرَيْشٍ، مِمَّنْ أُصِيبَ آبَاؤُهُمْ وَأَبْنَاؤُهُمْ وَإِخْوَانُهُمْ يَوْمَ بَدْرٍ، فَكَلَّمُوا أَبَا سُفْيَانَ بْنَ حَرْبٍ، وَمَنْ كَانَتْ لَهُ فِي تِلْكَ الْعِيرِ مِنْ قُرَيْشٍ تِجَارَةٌ، فَقَالُوا: يَا مَعْشَرَ قُرَيْشٍ، إنَّ مُحَمَّدًا قَدْ وَتَرَكُمْ، وَقَتَلَ خِيَارَكُمْ، فَأَعِينُونَا بِهَذَا الْمَالِ عَلَى حَرْبِهِ، فَلَعَلَّنَا …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ2 ص60 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '38', num: 38, category: 'madinah', icon: '🏛️', title: 'الخندق', location: 'جبل سلع', date: '627م', summary: 'تحزب القبائل وحفر الخندق ورد الله للأحزاب.', lat: 24.4833, lng: 39.5933, image: 'https://images.unsplash.com/photo-1509316785289-025f5b846b35?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=38', history: 'في شوال من السنة الخامسة للهجرة، سنة 627م، سعى نفر من زعماء يهود بني النضير، بعد إجلائهم عن المدينة، في تأليب القبائل، فاجتمعت قريش وغطفان وحلفاؤهما في نحو عشرة آلاف لاستئصال المسلمين. فاستشار النبي ﷺ أصحابه، فأشار سلمان الفارسي بحفر خندق في الجهة الشمالية المكشوفة من المدينة، إذ كانت الحِرار والنخيل تحمي بقية جهاتها. فحفره المسلمون، وهم نحو ثلاثة آلاف، في أيام شديدة البرد والجوع، والنبي ﷺ يحمل التراب معهم وقد ربط على بطنه الحجر.\n\nفوجئت الأحزاب بالخندق، وهو مكيدة لم تكن العرب تعرفها، فأقامت تحاصر المدينة قريبًا من شهر. واشتد الكرب حين نقضت بنو قريظة عهدها من داخل المدينة، حتى وصف القرآن الحال: «وإذ زاغت الأبصار وبلغت القلوب الحناجر». وعبر عمرو بن عبد ودّ الخندق فبارزه علي بن أبي طالب فقتله. وأسلم نُعيم بن مسعود فخذّل بين الأحزاب. ثم أرسل الله عليهم ريحًا باردة اقتلعت خيامهم وأطفأت نيرانهم، فرحلوا خائبين. وقال النبي ﷺ: «الآن نغزوهم ولا يغزوننا».', details: '<p class="summary-text">تحزبت القبائل في نحو عشرة آلاف لاستئصال المسلمين، فحفروا الخندق، وردّ الله الأحزاب بالريح.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  إنَّهُ كَانَ مِنْ حَدِيثِ الْخَنْدَقِ أَنَّ نَفَرًا مِنْ الْيَهُودِ، مِنْهُمْ: سَلَّامُ بْنُ أَبِي الْحَقِيقِ النَّضْرِيُّ ، وَحُيَيُّ بْنُ أَخْطَبَ النَّضْرِيُّ، وَكِنَانَةُ بْنُ أَبِي الْحَقِيقِ النَّضْرِيُّ، وَهَوْذَةُ بْنُ قَيْسٍ الْوَائِلِيُّ، وَأَبُو عَمَّارٍ الْوَائِلِيُّ، فِي نَفَرٍ مِنْ بَنِي النَّضِيرِ، وَنَفَرٍ مِنْ بَنِي وَائِلٍ، وَهُمْ الَّذِينَ حَزَّبُوا الْأَحْزَابَ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم، خَرَجُوا حَتَّى قَدِمُوا عَلَى قُرَيْشٍ مَكَّةَ، فَدَعَوْهُمْ إلَى حَرْبِ رَسُولِ اللَّهِ صلى الله عليه وسلم، وَقَالُوا: إنَّا سَنَكُونُ مَعَكُمْ عَلَيْهِ، حَتَّى نَسْتَأْصِلَهُ، فَقَالَتْ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ2 ص214 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '39', num: 39, category: 'madinah', icon: '📜', title: 'صلح الحديبية', location: 'الحديبية', date: '628م', summary: 'هدنة عشر سنين وبيعة الرضوان.', lat: 21.4420, lng: 39.6380, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=39', history: 'في ذي القعدة من السنة السادسة للهجرة، سنة 628م، خرج النبي ﷺ في نحو ألف وأربعمئة من أصحابه معتمرين، يسوقون الهدي ولا يحملون إلا سلاح المسافر. فصدّتهم قريش، فنزل بالحديبية على طرف الحرم. وأرسل عثمان بن عفان إلى مكة يخبرهم أنه لم يأتِ لقتال، فاحتبسوه وشاع أنه قُتل، فبايع الصحابة النبي ﷺ تحت الشجرة على ألا يفرّوا، وهي بيعة الرضوان التي نزل فيها: «لقد رضي الله عن المؤمنين إذ يبايعونك تحت الشجرة».\n\nثم أرسلت قريش سهيل بن عمرو، فتم الصلح على وضع الحرب عشر سنين، وأن يرجع المسلمون عامهم هذا ويعتمروا من قابل، وأن يُردّ من جاء من قريش إلى المدينة بغير إذن وليّه، وأن من شاء دخل في عهد أحد الفريقين. وشقّ بعض الشروط على الصحابة، حتى تأخروا عن التحلل، فأشارت أم سلمة على النبي ﷺ أن يبدأ بنفسه ففعل فتبعوه. وفي طريق العودة نزلت سورة الفتح: «إنا فتحنا لك فتحًا مبينًا». وقد أمن الناس فانتشر الإسلام، ودخل فيه خلال سنتين أكثر ممن دخل قبل ذلك.', details: '<p class="summary-text">خرج النبي ﷺ معتمرًا فصدّته قريش، فكانت بيعة الرضوان ثم صلح عشر سنين سماه القرآن فتحًا مبينًا.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: ثُمَّ أَقَامَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِالْمَدِينَةِ شَهْرَ رَمَضَانَ وَشَوَّالًا، وَخَرَجَ فِي ذِي الْقَعْدَةِ مُعْتَمِرًا، لَا يُرِيدُ حَرْبًا. قَالَ ابْنُ هِشَامٍ: وَاسْتَعْمَلَ عَلَى الْمَدِينَةِ نُمَيْلَةُ بْنُ عَبْدِ اللَّهِ اللَّيْثِيُّ. قَالَ ابْنُ إسْحَاقَ: وَاسْتَنْفَرَ الْعَرَبَ وَمَنْ حَوْلَهُ مِنْ أَهْلِ الْبَوَادِي مِنْ الْأَعْرَابِ لِيَخْرُجُوا مَعَهُ، وَهُوَ يَخْشَى مِنْ قُرَيْشٍ الَّذِي صَنَعُوا، أَنْ يَعْرِضُوا لَهُ بِحَرْبِ أَوْ يَصُدُّوهُ عَنْ الْبَيْتِ، فَأَبْطَأَ عَلَيْهِ كَثِيرٌ مِنْ الْأَعْرَابِ، وَخَرَجَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِمَنْ مَعَهُ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ2 ص308 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '40', num: 40, category: 'madinah', icon: '🕌', title: 'مراسلة الملوك', location: 'المدينة المنورة', date: '628م', summary: 'رسائل النبي ﷺ لكسرى وهرقل والنجاشي.', lat: 24.4672, lng: 39.6112, image: 'https://images.unsplash.com/photo-1580418827493-f2b22c0a76cb?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=40', history: 'بعد صلح الحديبية أمن النبي ﷺ جانب قريش، فتوجّه بدعوته إلى خارج الجزيرة، تحقيقًا لعموم رسالته: «وما أرسلناك إلا كافة للناس بشيرًا ونذيرًا». وقيل له إن الملوك لا يقرؤون كتابًا إلا مختومًا، فاتخذ خاتمًا من فضة نقشه «محمد رسول الله» كما في الصحيحين. ثم بعث رسله في أواخر السنة السادسة وأوائل السابعة للهجرة.\n\nحمل دِحية الكلبي كتابه إلى هرقل عظيم الروم، ونصّه في صحيح البخاري: «أسلم تسلم، يؤتك الله أجرك مرتين»، وفيه آية: «قل يا أهل الكتاب تعالوا إلى كلمة سواء بيننا وبينكم». فسأل هرقل أبا سفيان عن أحوال النبي ﷺ وأقرّ بصدق صفاته لكنه ضنّ بملكه. وحمل عبد الله بن حذافة السهمي كتابه إلى كسرى ملك فارس فمزّقه، فدعا النبي ﷺ أن يُمزَّق ملكه. وبعث عمرو بن أمية الضمري إلى النجاشي، وحاطب بن أبي بلتعة إلى المقوقس عظيم مصر، فأكرم الرسول وبعث بهدايا. وبعث كذلك إلى أمراء الغساسنة واليمامة والبحرين وعُمان، فأسلم بعضهم.', details: '<p class="summary-text">بعد الحديبية كتب النبي ﷺ إلى هرقل وكسرى والنجاشي والمقوقس وغيرهم يدعوهم إلى الإسلام.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ هِشَامٍ: وَقَدْ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم بَعَثَ إلَى الْمُلُوكِ رُسُلًا مِنْ أَصْحَابِهِ، وَكَتَبَ مَعَهُمْ إلَيْهِمْ يَدْعُوهُمْ إلَى الْإِسْلَامِ. قَالَ ابْنُ هِشَامٍ: حَدَّثَنِي مَنْ أَثِقُ بِهِ عَنْ أَبِي بَكْرٍ الْهُذَلِيِّ قَالَ: بَلَغَنِي أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم خَرَجَ عَلَى أَصْحَابِهِ ذَاتَ يَوْمٍ بَعْدَ عُمْرَتِهِ الَّتِي صُدَّ عَنْهَا يَوْمَ الْحُدَيْبِيَةِ، فَقَالَ: أَيُّهَا النَّاسُ، إنَّ اللَّهَ قَدْ بَعَثَنِي رَحْمَةً وَكَافَّةً، فَلَا تَخْتَلِفُوا عَلَيَّ كَمَا اخْتَلَفَ الْحَوَارِيُّونَ عَلَى عِيسَى بْنِ مَرْيَمَ، فَقَالَ أَصْحَابُهُ: وَكَيْفَ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ2 ص606 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '41', num: 41, category: 'madinah', icon: '⚔', title: 'فتح خيبر', location: 'خيبر', date: '628م', summary: 'سار لحصون خيبر ففتحها.', lat: 25.6969, lng: 39.2947, image: 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=41', history: 'كانت خيبر واحة حصينة شمال المدينة، كثيرة النخل والحصون، وقد صارت بعد إجلاء بني النضير مركزًا للتأليب على المسلمين، ومنها خرج من حزّب الأحزاب يوم الخندق. فلما أمن النبي ﷺ جانب قريش بصلح الحديبية، سار إليها في المحرم من السنة السابعة للهجرة، سنة 628م، في نحو ألف وأربعمئة ممن شهدوا الحديبية. فحاصر حصونها واحدًا بعد واحد: ناعم، والصعب بن معاذ، والقَموص، ثم الوَطيح والسُّلالم.\n\nواستعصى أحد الحصون أيامًا، فقال ﷺ كما في الصحيحين: «لأعطينّ الراية غدًا رجلًا يحب الله ورسوله ويحبه الله ورسوله، يفتح الله على يديه». فدعا عليًّا وكان يشتكي عينيه، فبصق فيهما ودعا له فبرئ، وأوصاه: «لأن يهدي الله بك رجلًا واحدًا خير لك من حُمر النعم». ففتح الله عليه. ثم صالح أهل خيبر على أن يبقوا في أرضهم يعملون فيها ولهم نصف ثمرها. وفي خيبر قدم جعفر بن أبي طالب ومن معه من مهاجري الحبشة، وتزوج النبي ﷺ صفية بنت حُيي.', details: '<p class="summary-text">سار النبي ﷺ إلى حصون خيبر ففتحها، وأعطى الراية علي بن أبي طالب، وقدم جعفر من الحبشة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ مُحَمَّدُ بْنُ إسْحَاقَ : ثُمَّ أَقَامَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِالْمَدِينَةِ حِينَ رَجَعَ مِنْ الْحُدَيْبِيَةِ، ذَا الْحَجَّةِ وَبَعْضَ الْمُحَرَّمِ، وَوَلِيَ تِلْكَ الْحَجَّةَ الْمُشْرِكُونَ، ثُمَّ خَرَجَ فِي بَقِيَّةِ الْمُحَرَّمِ إلَى خَيْبَرَ. قَالَ ابْنُ هِشَامٍ: وَاسْتَعْمَلَ عَلَى الْمَدِينَةِ نُمَيْلَةَ بْنَ عَبْدِ اللَّهِ اللَّيْثَيَّ، وَدَفَعَ الرَّايَةَ إلَى عَلِيِّ بْنِ أَبِي طَالِبٍ رضي الله عنه، وَكَانَتْ بَيْضَاءَ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ2 ص328 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '42', num: 42, category: 'madinah', icon: '⚔', title: 'غزوة مؤتة', location: 'مؤتة', date: '629م', summary: 'مواجهة الروم واستشهاد القادة الثلاثة.', lat: 31.0667, lng: 35.6833, image: 'https://images.unsplash.com/photo-1565552643983-c44917a26ea3?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=42', history: 'في جمادى الأولى من السنة الثامنة للهجرة، سنة 629م، بعث النبي ﷺ جيشًا من ثلاثة آلاف إلى تخوم الشام، بعد أن قتل شرحبيل بن عمرو الغساني رسوله الحارث بن عمير الأزدي، وكان قتل الرسل من أعظم الجنايات. وأمّر على الجيش زيد بن حارثة، وقال: «إن قُتل زيد فجعفر، وإن قُتل جعفر فعبد الله بن رواحة». فلما بلغوا مؤتة، وهي اليوم في جنوب الأردن، وجدوا أمامهم جموعًا من الروم وحلفائهم من العرب تفوقهم أضعافًا كثيرة.\n\nتشاور المسلمون ثم مضوا للقتال. فقاتل زيد بالراية حتى استُشهد، ثم أخذها جعفر فقاتل حتى قُطعت يداه واستُشهد، فلُقّب بذي الجناحين، ثم أخذها ابن رواحة فاستُشهد. فاصطلح الناس على خالد بن الوليد، فقاتل قتالًا شديدًا، وفي البخاري أنه قال: «لقد انقطعت في يدي يوم مؤتة تسعة أسياف». ثم غيّر ترتيب الجيش وانحاز به انحيازًا منظّمًا حفظ به المسلمين. وكان النبي ﷺ قد نعى القادة الثلاثة في المدينة قبل أن يأتي الخبر وعيناه تذرفان، وقال: «حتى أخذ الراية سيف من سيوف الله».', details: '<p class="summary-text">أول مواجهة مع الروم: استشهد القادة الثلاثة زيد وجعفر وابن رواحة، ثم انحاز خالد بالجيش.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: حَدَّثَنِي مُحَمَّدُ بْنُ جَعْفَرِ بْنِ الزُّبَيْرِ، عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ، قَالَ: بَعَثَ رَسُولُ اللَّهِ صلى الله عليه وسلم بَعْثَةَ إلَى مُؤْتَةَ فِي جُمَادَى الْأُولَى سَنَةَ ثَمَانٍ، وَاسْتَعْمَلَ عَلَيْهِمْ زَيْدَ بْنَ حَارِثَةَ وَقَالَ: إنْ أُصِيبَ زَيْدٌ فَجَعْفَرُ بْنُ أَبِي طَالِبٍ عَلَى النَّاسِ، فَإِنْ أُصِيبَ جَعْفَرٌ فَعَبْدُ اللَّهِ بْنُ رَوَاحَةَ عَلَى النَّاسِ فَتَجَهَّزَ النَّاسُ ثُمَّ تَهَيَّئُوا لِلْخُرُوجِ، وَهُمْ ثَلَاثَةُ آلَافٍ، فَلَمَّا حَضَرَ خُرُوجَهُمْ وَدَّعَ النَّاسُ أُمَرَاءَ رَسُولِ اللَّهِ صلى الله عليه وسلم وَسَلَّمُوا عَلَيْهِمْ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ2 ص373 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '43', num: 43, category: 'madinah', icon: '⚔', title: 'فتح مكة', location: 'مكة المكرمة', date: '630م', summary: 'دخول مكة فاتحاً وتحطيم الأصنام.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=43', history: 'أعانت قريش حلفاءها بني بكر على خزاعة حلفاء النبي ﷺ فقتلوا منهم رجالًا، فكان ذلك نقضًا لصلح الحديبية. وقدم عمرو بن سالم الخزاعي المدينة يستنصر، ثم جاء أبو سفيان يطلب تجديد العهد فلم يُجَب. وتجهّز النبي ﷺ في كتمان شديد، وخرج في رمضان من السنة الثامنة للهجرة، يناير 630م، في عشرة آلاف. فلما نزل بمرّ الظهران أسلم أبو سفيان، وأعلن النبي ﷺ الأمان: «من دخل دار أبي سفيان فهو آمن، ومن أغلق عليه بابه فهو آمن، ومن دخل المسجد فهو آمن».\n\nودخل ﷺ مكة من أعلاها خاشعًا متواضعًا يقرأ سورة الفتح، ولم يقع قتال إلا مناوشة يسيرة في الجهة التي دخل منها خالد بن الوليد. وطاف بالبيت وحوله ثلاثمئة وستون صنمًا، فجعل يطعنها وهو يقول: «جاء الحق وزهق الباطل». ثم خاطب أهل مكة الذين آذوه وأخرجوه، فعفا عنهم، ويروي ابن إسحاق قوله: «اذهبوا فأنتم الطلقاء». وردّ مفتاح الكعبة إلى عثمان بن طلحة، وأذّن بلال فوق الكعبة. ودخل الناس بعد الفتح في دين الله أفواجًا.', details: '<p class="summary-text">نقضت قريش عهد الحديبية، فسار النبي ﷺ بعشرة آلاف، ودخل مكة فاتحًا وعفا عن أهلها وطهّر البيت من الأصنام.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: ثُمَّ أَقَامَ رَسُولُ اللَّهِ صلى الله عليه وسلم بَعْدَ بَعْثِهِ إلَى مُؤْتَةَ جُمَادَى الْآخِرَةَ وَرَجَبًا. ثُمَّ إنَّ بَنِي بَكْرِ بْنِ عَبْدِ مَنَاةَ بْنِ كِنَانَةَ عَدَتْ عَلَى خُزَاعَةَ، وَهُمْ عَلَى مَاءٍ لَهُمْ بِأَسْفَلِ مَكَّةَ يُقَالُ لَهُ: الْوَتِيرُ، وَكَانَ الَّذِي هَاجَ مَا بَيْنَ بَنِي بَكْرٍ وَخُزَاعَةَ أَنَّ رَجُلًا مِنْ بَنِي الْحَضْرَمِيِّ، وَاسْمُهُ مَالِكُ بْنُ عَبَّادٍ- وَحِلْفُ الْحَضْرَمِيِّ يَوْمَئِذٍ إلَى الْأَسْوَدِ بْنِ رَزْنٍ- خَرَجَ تَاجِرًا، فَلَمَّا تَوَسَّطَ أَرْضَ خُزَاعَةَ، عَدَوْا عَلَيْهِ فَقَتَلُوهُ، وَأَخَذُوا مَالَهُ، فَعَدَتْ بَنُو بَكْرٍ عَلَى …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ2 ص389 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '44', num: 44, category: 'madinah', icon: '🏛️', title: 'حنين والطائف', location: 'وادي حنين', date: '630م', summary: 'الانتصار في حنين ثم حصار الطائف.', lat: 21.4670, lng: 40.0000, image: 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=44', history: 'بعد فتح مكة حشدت هوازن وثقيف جموعها بقيادة مالك بن عوف النصري، وساق معه النساء والأموال ليثبت الناس. فخرج إليهم النبي ﷺ في شوال من السنة الثامنة للهجرة، سنة 630م، في اثني عشر ألفًا: عشرة آلاف ممن فتحوا مكة وألفين من أهلها. فأعجبت الكثرة بعض المسلمين وقالوا: لن نُغلب اليوم من قلة. وكان العدو قد كمن في شعاب وادي حنين، فلما انحدر المسلمون في غبش الصبح انهال عليهم بالنبل، فانكشف أكثرهم.\n\nوثبت النبي ﷺ على بغلته وهو يقول: «أنا النبي لا كذب، أنا ابن عبد المطلب»، ونادى العباس بأصحاب الشجرة فأقبلوا، فكان النصر. وفي ذلك نزل: «ويوم حنين إذ أعجبتكم كثرتكم فلم تغنِ عنكم شيئًا». ثم حاصر الطائف بضعة عشر يومًا ورفع الحصار، ودعا: «اللهم اهدِ ثقيفًا»، فجاؤوا مسلمين بعد عام. وقسم الغنائم بالجِعرانة فتألّف بها قلوب حديثي العهد بالإسلام، وطيّب خواطر الأنصار بقوله: «ألا ترضون أن يذهب الناس بالشاة والبعير وترجعون برسول الله إلى رحالكم؟». وردّ على هوازن سبيهم حين أسلموا.', details: '<p class="summary-text">اغترّ بعض المسلمين بكثرتهم فانكشفوا أول الأمر، ثم ثبت النبي ﷺ فكان النصر، ثم حوصرت الطائف.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: وَلَمَّا سَمِعَتْ هَوَازِنُ بِرَسُولِ اللَّهِ صلى الله عليه وسلم وَمَا فَتَحَ اللَّهُ عَلَيْهِ مِنْ مَكَّةَ ، جَمَعَهَا مَالِكُ بْنُ عَوْفٍ النَّصْرِيُّ، فَاجْتَمَعَ إلَيْهِ مَعَ هَوَازِنَ ثَقِيفٌ كُلُّهَا، وَاجْتَمَعَتْ نَصْرٌ وَجُشَمٌ كُلُّهَا، وَسَعْدُ بْنُ بَكْرٍ، وَنَاسٌ مِنْ بَنِي هِلَالٍ، وَهُمْ قَلِيلٌ، وَلَمْ يَشْهَدْهَا مِنْ قَيْسِ عَيْلَانَ إلَّا هَؤُلَاءِ، وَغَابَ عَنْهَا فَلَمْ يَحْضُرْهَا مِنْ هَوَازِنَ كَعْبٌ وَلَا كِلَابٌ، وَلَمْ يَشْهَدْهَا مِنْهُمْ أَحَدٌ لَهُ اسْمٌ، وَفِي بَنِي جُشَمٍ دُرَيْدُ بْنُ الصِّمَّةِ شَيْخٌ كَبِيرٌ، لَيْسَ فِيهِ شَيْءٌ إلَّا التَّيَمُّنَ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ2 ص437 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '45', num: 45, category: 'madinah', icon: '⚔', title: 'غزوة تبوك', location: 'تبوك', date: '630م', summary: 'جيش العسرة لملاقاة الروم.', lat: 28.3835, lng: 36.5662, image: 'https://images.unsplash.com/photo-1509316785289-025f5b846b35?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=45', history: 'في رجب من السنة التاسعة للهجرة، سنة 630م، بلغ النبي ﷺ أن الروم تجمع جموعها على أطراف الشام. فأمر الناس بالتجهز، وأعلن وجهته على غير عادته لبُعد الشقة وشدة الحر، وكان ذلك وقت نضج الثمار وعسرة في المال، فسُمّي الجيش «جيش العسرة». وتسابق الصحابة في البذل: فجهّز عثمان بن عفان جانبًا عظيمًا من الجيش، وجاء أبو بكر بماله كله وعمر بنصف ماله. وجاء فقراء يسألون ما يركبون فلم يجدوا، فتولّوا وأعينهم تفيض من الدمع. وتخلّف المنافقون يعتذرون. واستخلف النبي ﷺ عليًّا على أهله وقال له: «أما ترضى أن تكون مني بمنزلة هارون من موسى؟».\n\nسار ﷺ في نحو ثلاثين ألفًا حتى بلغ تبوك، فأقام بها نحو عشرين ليلة ولم يلقَ كيدًا. وصالح صاحب أيلة وأهل جرباء وأذرح، وبعث خالدًا إلى أُكيدر دومة الجندل. ثم عاد وقد ثبتت هيبة الدولة في الشمال. ونزلت سورة التوبة تكشف المنافقين، وتذكر توبة الله على الثلاثة الذين خُلّفوا، وفيهم كعب بن مالك، بعد خمسين ليلة لصدقهم. وكانت تبوك آخر غزواته ﷺ.', details: '<p class="summary-text">خرج النبي ﷺ في نحو ثلاثين ألفًا في حر شديد لملاقاة الروم، فلم يلقَ قتالًا وعقد معاهدات مع أهل الأطراف.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ: حَدَّثَنَا أَبُو مُحَمَّدٍ عَبْدُ الْمَلِكِ بْنِ هِشَامٍ، قَالَ زِيَادُ بْنُ عَبْدِ اللَّهِ الْبَكَّائِيَّ، عَنْ مُحَمَّدِ بْنِ إسْحَاقَ الْمُطَّلِبِيِّ، قَالَ: ثُمَّ أَقَامَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِالْمَدِينَةِ مَا بَيْنَ ذِي الْحَجَّةِ إلَى رَجَبٍ، ثُمَّ أَمَرَ النَّاسَ بِالتَّهَيُّؤِ لِغَزْوِ الرُّومِ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ2 ص515 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '46', num: 46, category: 'madinah', icon: '🕌', title: 'عام الوفود', location: 'المدينة المنورة', date: '630 - 631م', summary: 'إقبال القبائل للمدينة لإعلان إسلامها.', lat: 24.4672, lng: 39.6112, image: 'https://images.unsplash.com/photo-1580418827493-f2b22c0a76cb?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=46', history: 'بعد فتح مكة وعودة النبي ﷺ من تبوك، أيقنت قبائل العرب أن لا طاقة لها بمعاداة الإسلام، وكانت تنتظر ما يكون بينه وبين قريش. فأقبلت وفودها على المدينة من كل ناحية في السنة التاسعة للهجرة وما بعدها، حتى سُمّيت «سنة الوفود»، وصدق قول الله تعالى: «إذا جاء نصر الله والفتح، ورأيت الناس يدخلون في دين الله أفواجًا». وذكر أهل السير عشرات الوفود، منها وفد ثقيف، وبني تميم، وعبد القيس، وبني حنيفة، وطيّئ وفيهم عدي بن حاتم، وملوك حِمير، ووفد نصارى نجران الذين صالحهم النبي ﷺ وكتب لهم عهدًا.\n\nوكان ﷺ يكرم الوفود وينزلهم ويعلّمهم دينهم، ويبعث معهم من يقرئهم القرآن، وبعث معاذ بن جبل وأبا موسى الأشعري إلى اليمن وأوصاهما: «يسّرا ولا تعسّرا، وبشّرا ولا تنفّرا». وفي موسم السنة التاسعة حجّ أبو بكر الصديق بالناس أميرًا، وأتبعه النبي ﷺ عليًّا يقرأ على الناس صدر سورة براءة، ونودي: ألا يحج بعد العام مشرك، ولا يطوف بالبيت عريان.', details: '<p class="summary-text">أقبلت وفود القبائل من أنحاء الجزيرة إلى المدينة تعلن إسلامها، وحج أبو بكر بالناس.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: لَمَّا افْتَتَحَ رَسُولُ اللَّهِ صلى الله عليه وسلم مَكَّةَ، وَفَرَغَ مِنْ تَبُوكَ، وَأَسْلَمَتْ ثَقِيفٌ وَبَايَعَتْ، ضَرَبَتْ إلَيْهِ وُفُودُ الْعَرَبِ مِنْ كُلِّ وَجْهٍ. قَالَ ابْنُ هِشَامٍ: حَدَّثَنِي أَبُو عُبَيْدَةَ: أَنَّ ذَلِكَ فِي سَنَةِ تِسْعٍ، وَأَنَّهَا كَانَتْ تُسْمَى سَنَةَ الْوُفُودِ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ2 ص559 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '47', num: 47, category: 'hijra', icon: '🏛️', title: 'حجة الوداع', location: 'جبل الرحمة', date: '632م', summary: 'خطبة عرفة ونزول: اليوم أكملت لكم دينكم.', lat: 21.3549, lng: 39.9841, image: 'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=47', history: 'في السنة العاشرة للهجرة أعلن النبي ﷺ أنه حاجّ، فقدم المدينة خلق كثير يريدون أن يأتمّوا به. وخرج لخمس بقين من ذي القعدة، وحجّ معه عشرات الألوف، وروى جابر بن عبد الله صفة حجته في حديثه الطويل عند مسلم. وكان يقول: «خذوا عني مناسككم، فإني لا أدري لعلي لا أحج بعد حجتي هذه»، فلذلك سُمّيت حجة الوداع.\n\nوفي يوم عرفة، التاسع من ذي الحجة، مارس 632م، خطب الناس خطبته الجامعة فقال: «إن دماءكم وأموالكم حرام عليكم كحرمة يومكم هذا، في شهركم هذا، في بلدكم هذا». ووضع أمر الجاهلية ودماءها ورباها، وبدأ بدم ابن عمه وربا عمه العباس. وأوصى بالنساء خيرًا: «فاتقوا الله في النساء»، وقال: «وقد تركت فيكم ما لن تضلّوا بعده إن اعتصمتم به: كتاب الله». ثم استشهدهم: «ألا هل بلّغت؟» قالوا: نعم. قال: «اللهم اشهد». وفي ذلك اليوم نزل قوله تعالى: «اليوم أكملت لكم دينكم وأتممت عليكم نعمتي ورضيت لكم الإسلام دينًا».', details: '<p class="summary-text">حج النبي ﷺ حجته الوحيدة، وخطب في عرفة خطبته الجامعة، ونزل: «اليوم أكملت لكم دينكم».</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: ثُمَّ مَضَى رَسُولُ اللَّهِ صلى الله عليه وسلم عَلَى حَجِّهِ، فَأَرَى النَّاسَ مَنَاسِكَهُمْ، وَأَعْلَمَهُمْ سُنَنَ حَجِّهِمْ، وَخَطَبَ النَّاسَ خُطْبَتَهُ الَّتِي بَيَّنَ فِيهَا مَا بَيَّنَ، فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: أَيُّهَا النَّاسُ، اسْمَعُوا قَوْلِي، فَإِنِّي لَا أَدْرِي لَعَلِّي لَا أَلْقَاكُمْ بَعْدَ عَامِي هَذَا بِهَذَا الْمَوْقِفِ أَبَدًا، أَيُّهَا النَّاسُ، إنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ عَلَيْكُمْ حَرَامٌ إلَى أَنْ تَلْقَوْا رَبَّكُمْ، كَحُرْمَةِ يَوْمِكُمْ هَذَا، وَكَحُرْمَةِ شَهْرِكُمْ هَذَا، وَإِنَّكُمْ سَتَلْقَوْنَ رَبَّكُمْ، فَيَسْأَلُكُمْ عَنْ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ2 ص603 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '48', num: 48, category: 'madinah', icon: '🕌', title: 'وفاة النبي ﷺ', location: 'المدينة المنورة', date: '632م', summary: 'انتقاله للرفيق الأعلى عن 63 عاماً.', lat: 24.4672, lng: 39.6112, image: 'https://images.unsplash.com/photo-1580418827493-f2b22c0a76cb?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=48', history: 'بعد عودته من حجة الوداع بدأ بالنبي ﷺ المرض في أواخر صفر من السنة الحادية عشرة للهجرة. فلما اشتد عليه استأذن أزواجه أن يُمرَّض في بيت عائشة فأذنّ له. وأمر أبا بكر أن يصلي بالناس، وخرج إليهم يومًا فخطبهم وأوصاهم بالأنصار خيرًا. وكان من آخر وصاياه: «الصلاة، وما ملكت أيمانكم»، وتحذيره من اتخاذ القبور مساجد. وفي فجر يوم الاثنين كشف ستر الحجرة فنظر إلى أصحابه صفوفًا في الصلاة فتبسّم.\n\nوتوفي ﷺ ضحى ذلك اليوم، يوم الاثنين من ربيع الأول، والمشهور أنه الثاني عشر منه، سنة 11هـ الموافق يونيو 632م، وهو ابن ثلاث وستين سنة، ورأسه على صدر عائشة، وآخر ما قال: «اللهم الرفيق الأعلى». وذهل الناس، حتى قام أبو بكر فقال: «من كان يعبد محمدًا فإن محمدًا قد مات، ومن كان يعبد الله فإن الله حي لا يموت»، وتلا: «وما محمد إلا رسول قد خلت من قبله الرسل». ودُفن ﷺ في حجرة عائشة حيث قُبض، وبايع المسلمون أبا بكر خليفة.', details: '<p class="summary-text">اشتد المرض بالنبي ﷺ في بيت عائشة، وانتقل إلى الرفيق الأعلى يوم الاثنين عن ثلاث وستين سنة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: فَبَيْنَا النَّاسُ عَلَى ذَلِكَ اُبْتُدِئَ رَسُول الله صلى الله عليه وسلم يشكوه الَّذِي قَبَضَهُ اللَّهُ فِيهِ، إلَى مَا أَرَادَ بِهِ مِنْ كَرَامَتِهِ وَرَحْمَتِهِ، فِي لَيَالٍ بَقِينَ مِنْ صَفَرٍ، أَوْ فِي أَوَّلِ شَهْرِ رَبِيعٍ الْأَوَّلِ، فَكَانَ أَوَّلُ مَا اُبْتُدِئَ بِهِ مِنْ ذَلِكَ، فِيمَا ذُكِرَ لِي، أَنَّهُ خَرَجَ إلَى بَقِيعِ الْغَرْقَدِ، مِنْ جَوْفِ اللَّيْلِ، فَاسْتَغْفَرَ لَهُمْ، ثُمَّ رَجَعَ إلَى أَهْلِهِ، فَلَمَّا أَصْبَحَ اُبْتُدِئَ بِوَجَعِهِ مِنْ يَوْمِهِ ذَلِكَ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ2 ص642 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '49', num: 49, category: 'caliphs', icon: '🕌', title: 'الجمع الأول', location: 'المدينة المنورة', date: '632 - 634م', summary: 'جمع أبو بكر القرآن بعد معركة اليمامة.', lat: 24.4672, lng: 39.6112, image: 'https://images.unsplash.com/photo-1580418827493-f2b22c0a76cb?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=49', history: 'تولى أبو بكر الصديق الخلافة سنة 11هـ، فواجه ردّة قبائل من العرب ومدّعي النبوة. وفي معركة اليمامة ضد مسيلمة الكذاب استُشهد عدد كبير من حفّاظ القرآن. فخشي عمر بن الخطاب أن يذهب شيء من القرآن بذهاب حملته، فأشار على أبي بكر بجمعه. روى البخاري عن زيد بن ثابت أن أبا بكر تردّد أولًا وقال: كيف أفعل شيئًا لم يفعله رسول الله ﷺ؟ فقال عمر: هو والله خير. فلم يزل يراجعه حتى شرح الله صدره لذلك.\n\nواختار أبو بكر لهذه المهمة زيد بن ثابت، وكان شابًّا عاقلًا من كتبة الوحي بين يدي النبي ﷺ. قال زيد: «فوالله لو كلّفوني نقل جبل من الجبال ما كان أثقل عليّ مما أمرني به من جمع القرآن». فتتبّعه يجمعه من العُسُب واللِّخاف وصدور الرجال، ولا يقبل المكتوب إلا إذا شهد له الحفظ وثبت أنه كُتب بين يدي النبي ﷺ. فاجتمع القرآن في صحف مرتبة محفوظة عند أبي بكر حتى توفي، ثم عند عمر، ثم عند ابنته حفصة أم المؤمنين. وكان القرآن قبل ذلك مكتوبًا كله في عهد النبي ﷺ لكنه مفرّق غير مجموع في موضع واحد.', details: '<p class="summary-text">بعد استشهاد كثير من القرّاء يوم اليمامة، جمع أبو بكر القرآن في صحف واحدة بإشارة عمر، على يد زيد بن ثابت.</p>' },
  { id: '50', num: 50, category: 'caliphs', icon: '🕌', title: 'تعليم الأمصار', location: 'المدينة المنورة', date: '634 - 644م', summary: 'إرسال عمر معلّمي القرآن إلى الشام والأمصار.', lat: 24.4672, lng: 39.6112, image: 'https://images.unsplash.com/photo-1580418827493-f2b22c0a76cb?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=50', history: 'تولى عمر بن الخطاب الخلافة سنة 13هـ، وفي عهده اتسعت الفتوح فشملت الشام والعراق ومصر وفارس، ودخل في الإسلام أمم لا تعرف العربية ولم تسمع القرآن من قبل. فكان من أعظم ما عُني به تعليم الناس كتاب الله. وبقيت الصحف التي جُمعت في عهد أبي بكر محفوظة عنده، وهو صاحب الإشارة بجمعها، ثم صارت بعده إلى ابنته حفصة.\n\nوبعث كبار القرّاء من الصحابة معلّمين إلى الأمصار. يروي ابن سعد أن يزيد بن أبي سفيان كتب إليه أن أهل الشام قد كثروا واحتاجوا إلى من يعلّمهم القرآن ويفقّههم، فأرسل معاذ بن جبل وعبادة بن الصامت وأبا الدرداء، فتوزعوا على حمص ودمشق وفلسطين. وبعث عبد الله بن مسعود إلى الكوفة معلّمًا ووزيرًا، وكتب إلى أهلها: إني آثرتكم بعبد الله على نفسي. وكان أبو موسى الأشعري يقرئ الناس بالبصرة. وفي رمضان جمع الناس في المسجد النبوي على قارئ واحد هو أُبيّ بن كعب في صلاة التراويح كما في صحيح البخاري. وبهذه الحلقات نشأت مدارس الإقراء الأولى في الأمصار.', details: '<p class="summary-text">صاحب الإشارة بالجمع الأول، حفظ الصحف في خلافته، وأرسل معلّمي القرآن إلى الشام، وجمع الناس في رمضان على قارئ واحد.</p>' },
  { id: '51', num: 51, category: 'caliphs', icon: '🕌', title: 'المصحف العثماني', location: 'المدينة المنورة', date: '644 - 656م', summary: 'نسخ عثمان المصاحف وأرسلها لكل أفق.', lat: 24.4672, lng: 39.6112, image: 'https://images.unsplash.com/photo-1580418827493-f2b22c0a76cb?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=51', history: 'في خلافة عثمان بن عفان اتسعت البلاد وتفرّق الصحابة في الأمصار، وأخذ أهل كل مصر القراءة عمّن نزل بهم من الصحابة على ما أُذن به من الأحرف. فلما اجتمع أهل الشام وأهل العراق في فتح أرمينية وأذربيجان اختلفوا في القراءة حتى كاد بعضهم يخطّئ بعضًا. ففزع حذيفة بن اليمان إلى عثمان وقال، كما روى البخاري: «يا أمير المؤمنين، أدرك هذه الأمة قبل أن يختلفوا في الكتاب اختلاف اليهود والنصارى».\n\nفاستشار عثمان الصحابة، وأرسل إلى حفصة فأخذ الصحف التي جُمعت في عهد أبي بكر، وأمر زيد بن ثابت وعبد الله بن الزبير وسعيد بن العاص وعبد الرحمن بن الحارث بن هشام أن ينسخوها في المصاحف، وقال للقرشيين الثلاثة: إذا اختلفتم أنتم وزيد في شيء فاكتبوه بلسان قريش، فإنما نزل بلسانهم. ثم ردّ الصحف إلى حفصة، وأرسل إلى كل أفق بمصحف، وأبقى بالمدينة مصحفًا عُرف بالإمام، وأمر بما سواها من الصحف أن يُحرق. فاجتمعت الأمة على مصحف واحد، وهو الرسم العثماني الذي تُكتب به المصاحف إلى اليوم.', details: '<p class="summary-text">لما اختلف الناس في القراءة، نسخ عثمان المصاحف من صحف حفصة بمشورة الصحابة، وأرسل إلى كل أفق بمصحف.</p>' },
  { id: '52', num: 52, category: 'caliphs', icon: '📜', title: 'إقرار المصحف', location: 'الكوفة', date: '656 - 661م', summary: 'إقرار علي بن أبي طالب لجمع المصحف وبقائه محل إجماع.', lat: 32.0292, lng: 44.3986, image: 'https://images.unsplash.com/photo-1565552643983-c44917a26ea3?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=52', history: 'بويع علي بن أبي طالب بالخلافة سنة 35هـ بعد استشهاد عثمان رضي الله عنهما، في زمن فتنة واضطراب، ثم اتخذ الكوفة مقرًّا لخلافته. ومع ما وقع في تلك السنين من خلاف سياسي، بقي المصحف الذي جمع عثمان الناس عليه بمنأى عن النزاع، وكان موقف علي منه حاسمًا في تثبيت الإجماع عليه.\n\nفقد روى ابن أبي داود في كتاب «المصاحف» عن سويد بن غفلة أن عليًّا قال: «لا تقولوا في عثمان إلا خيرًا، فوالله ما فعل الذي فعل في المصاحف إلا عن ملأ منا»، وقال: «لو وُلّيت لفعلت مثل الذي فعل». فقطع بذلك الطريق على من أراد الطعن في عمل عثمان، وبيّن أنه كان بمشورة الصحابة ورضاهم. وكان علي نفسه من كتبة الوحي ومن حفّاظ القرآن وأعلم الصحابة بتفسيره. ويُنسب إلى عهده بدء العناية بضبط العربية صيانةً لتلاوة القرآن من اللحن، على يد أبي الأسود الدؤلي. واستُشهد رضي الله عنه بالكوفة سنة 40هـ، وبقي المصحف الإمام محل إجماع الأمة جيلًا بعد جيل.', details: '<p class="summary-text">بويع علي بعد مقتل عثمان، ودافع عن جمعه للمصحف وأعلن أنه لو ولي لفعل مثله، فبقي المصحف الإمام محل إجماع.</p>' }
];
